//! Local DNSSEC chain-of-trust validation (+validate).
//!
//! Verifies RRSIGs, DS digests, and the chain from the answer's signing
//! zone up to the IANA root trust anchors — without trusting the
//! resolver's AD bit. RFC 4034/4035 canonical form, RFC 6840 clarifications.

use crate::error::DnsError;
use crate::parallel;
use crate::protocol::edns::EdnsOptions;
use crate::protocol::message::DnsMessage;
use crate::protocol::name::encode_name;
use crate::protocol::record::{RData, ResourceRecord};
use crate::protocol::types::{Rcode, RecordClass, RecordType};
use crate::transport;
use aws_lc_rs::{digest, signature};
use std::collections::HashMap;
use std::sync::Mutex;
use std::time::Duration;

/// IANA root zone trust anchors (DS form, SHA-256).
struct TrustAnchor {
    key_tag: u16,
    digest: &'static [u8],
}

const ROOT_ANCHORS: &[TrustAnchor] = &[
    // KSK-2017 (still published)
    TrustAnchor {
        key_tag: 20326,
        digest: &[
            0xE0, 0x6D, 0x44, 0xB8, 0x0B, 0x8F, 0x1D, 0x39, 0xA9, 0x5C, 0x0B, 0x0D, 0x7C, 0x65,
            0xD0, 0x84, 0x58, 0xE8, 0x80, 0x40, 0x9B, 0xBC, 0x68, 0x34, 0x57, 0x10, 0x42, 0x37,
            0xC7, 0xF8, 0xEC, 0x8D,
        ],
    },
    // KSK-2024
    TrustAnchor {
        key_tag: 38696,
        digest: &[
            0x68, 0x3D, 0x2D, 0x0A, 0xCB, 0x8C, 0x9B, 0x71, 0x2A, 0x19, 0x48, 0xB2, 0x7F, 0x74,
            0x12, 0x19, 0x29, 0x8D, 0x0A, 0x45, 0x0D, 0x61, 0x2C, 0x48, 0x3A, 0xF4, 0x44, 0xA4,
            0xC0, 0xFB, 0x2B, 0x16,
        ],
    },
];

#[derive(Debug, PartialEq)]
pub enum ChainStatus {
    /// Every link verified down from a root trust anchor.
    Secure,
    /// The chain legitimately ends: an unsigned delegation (no DS).
    Insecure(String),
    /// A signature, digest, or timing check failed.
    Bogus(String),
}

pub struct LinkReport {
    pub zone: String,
    pub detail: String,
    pub ok: bool,
}

impl LinkReport {
    fn ok(zone: impl Into<String>, detail: impl Into<String>) -> Self {
        LinkReport {
            zone: zone.into(),
            detail: detail.into(),
            ok: true,
        }
    }

    fn failed(zone: impl Into<String>, detail: impl Into<String>) -> Self {
        LinkReport {
            zone: zone.into(),
            detail: detail.into(),
            ok: false,
        }
    }
}

pub struct ValidationReport {
    pub links: Vec<LinkReport>,
    pub status: ChainStatus,
}

/// The records of one type within a message section.
fn records_of(section: &[ResourceRecord], rtype: RecordType) -> Vec<&ResourceRecord> {
    section.iter().filter(|rr| rr.rtype == rtype).collect()
}

/// The RRSIGs within a section that cover `rtype`.
fn rrsigs_covering(
    section: &[ResourceRecord],
    rtype: RecordType,
) -> impl Iterator<Item = &ResourceRecord> {
    section.iter().filter(
        move |rr| matches!(&rr.rdata, RData::RRSIG { type_covered, .. } if *type_covered == rtype),
    )
}

/// Record a failed link and end the walk as Bogus.
///
/// `detail` is the per-zone line; `reason` is the overall chain status, which
/// repeats the zone because it is shown on its own. Pairing the two here means
/// a Bogus status cannot be returned without the link that explains it.
fn bogus(
    mut links: Vec<LinkReport>,
    zone: impl Into<String>,
    detail: impl Into<String>,
    reason: impl Into<String>,
) -> Result<ValidationReport, DnsError> {
    links.push(LinkReport::failed(zone, detail));
    Ok(ValidationReport {
        links,
        status: ChainStatus::Bogus(reason.into()),
    })
}

/// Validate the answer's chain of trust by issuing our own DNSKEY/DS
/// queries through the given resolver and verifying everything locally.
#[allow(clippy::too_many_arguments)]
pub fn validate(
    server: &str,
    port: u16,
    answer: &DnsMessage,
    qname: &str,
    qtype: RecordType,
    timeout: Duration,
    cd: bool,
) -> Result<ValidationReport, DnsError> {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as u32)
        .unwrap_or(0);
    let fetch = |name: &str, rtype: RecordType| -> Result<DnsMessage, DnsError> {
        let edns = EdnsOptions {
            dnssec_ok: true,
            ..EdnsOptions::default()
        };
        let (query, id) = DnsMessage::build_query_with_class(
            name,
            rtype,
            RecordClass::IN,
            true,
            cd,
            Some(&edns),
        )?;
        complete_response(name, rtype, Duration::from_millis(150), || {
            let result =
                transport::send_query_with_retries(server, port, &query, false, timeout, 2)?
                    .verify_id(id)?;
            Ok(result.message)
        })
    };
    validate_with(answer, qname, qtype, now, &fetch)
}

/// How many times to ask again when a response is unusable.
const INCOMPLETE_RETRIES: u32 = 3;

/// Run `send` until it yields a response that can carry DNSSEC data.
///
/// Four kinds of response cannot, and none is evidence about the zone:
///
/// - Truncated. The transport already retries a truncated UDP response over
///   TCP, so a TC bit that reaches here was set on the TCP response itself.
/// - A failure such as SERVFAIL. The resolver did not answer the question; it
///   did not say the answer is empty.
/// - An empty answer to a DNSKEY query.
/// - Without an EDNS OPT record. Every query here sets the DO bit, and a
///   resolver that understood it answers with OPT. One without it is a
///   resolver that dropped the request's EDNS, and its DNSSEC records too.
///
/// Resolvers return each of these now and then, with an empty answer. Taken at
/// face value that reads as "this zone has no keys" or "no proof was sent",
/// and turns a resolver hiccup into a BOGUS verdict. It is a failed lookup:
/// ask again after `pause`, and if it keeps happening, say so rather than
/// judge the data.
fn complete_response(
    name: &str,
    rtype: RecordType,
    pause: Duration,
    send: impl Fn() -> Result<DnsMessage, DnsError>,
) -> Result<DnsMessage, DnsError> {
    let mut problem = "";
    for attempt in 0..=INCOMPLETE_RETRIES {
        if attempt > 0 {
            std::thread::sleep(pause * attempt);
        }
        let message = send()?;
        if message.header.tc {
            problem = "a truncated response";
        } else if !matches!(message.header.rcode, Rcode::NoError | Rcode::NxDomain) {
            // SERVFAIL and the like: the resolver did not answer. From a
            // validating resolver that can mean it judged the data bogus, in
            // which case +cd makes it hand the data over.
            problem = "a failure response";
        } else if message.edns.is_none() {
            problem = "a response without EDNS";
        } else if rtype == RecordType::DNSKEY
            && !message
                .answers
                .iter()
                .any(|rr| rr.rtype == RecordType::DNSKEY)
        {
            // DNSKEY is only ever asked of a zone that something claims to be
            // signed by, so "it has none" is never the expected answer.
            // Resolvers do return it in passing: 1.1.1.1 answered half of a
            // run of cdc.gov DNSKEY queries with an empty NOERROR.
            problem = "an empty answer";
        } else {
            return Ok(message);
        }
    }
    Err(DnsError::Protocol(format!(
        "resolver kept returning {} for {} {}; cannot validate (try another resolver, e.g. @1.1.1.1, or +cd)",
        problem, name, rtype
    )))
}

/// Core validation, parameterized over time and record fetching so tests
/// can run hermetically against captured fixtures.
pub fn validate_with(
    answer: &DnsMessage,
    qname: &str,
    qtype: RecordType,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
) -> Result<ValidationReport, DnsError> {
    // The walk asks for the same records more than once: a zone's DNSKEY is
    // fetched to check the answer's RRSIG, again when the chain reaches that
    // zone, and again as the "parent keys" that sign the child's DS. Validating
    // cloudflare.com issued eight queries for five distinct records, three of
    // them back-to-back repeats of the query before.
    //
    // Memoising per validation removes those without guessing at anything: a
    // zone's DNSKEY or DS cannot meaningfully change mid-walk, and reusing the
    // first response is what the chain is verified against anyway. Only
    // successes are cached - a failed fetch aborts the validation, so it never
    // gets a second chance to be wrong.
    let seen: Mutex<HashMap<(String, u16), DnsMessage>> = Mutex::new(HashMap::new());
    let fetch = &|name: &str, rtype: RecordType| -> Result<DnsMessage, DnsError> {
        let key = (name.to_string(), rtype.to_u16());
        if let Some(hit) = seen.lock().expect("fetch cache poisoned").get(&key) {
            return Ok(hit.clone());
        }
        let message = fetch(name, rtype)?;
        seen.lock()
            .expect("fetch cache poisoned")
            .insert(key, message.clone());
        Ok(message)
    };

    validate_answer(answer, qname, qtype, now, fetch, &mut Vec::new())
}

/// The validation itself. `trusted` holds zones already verified to the root;
/// it starts empty, except in tests that pin part of the chain.
fn validate_answer(
    answer: &DnsMessage,
    qname: &str,
    qtype: RecordType,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
    trusted: &mut Vec<String>,
) -> Result<ValidationReport, DnsError> {
    let mut links = Vec::new();

    // A response that is neither an answer nor a denial has nothing in it to
    // validate. SERVFAIL from a validating resolver often means the data
    // failed validation there; +cd asks it to hand the data over anyway.
    if !matches!(answer.header.rcode, Rcode::NoError | Rcode::NxDomain) {
        return Ok(ValidationReport {
            links,
            status: ChainStatus::Insecure(format!(
                "resolver answered {}; there is no answer to validate",
                answer.header.rcode
            )),
        });
    }

    // No OPT record means the resolver ignored the DO bit, so the response
    // holds no DNSSEC records whatever the zone publishes. Judging it would
    // blame the zone for the resolver.
    if answer.edns.is_none() {
        return Ok(ValidationReport {
            links,
            status: ChainStatus::Insecure(
                "the resolver's response has no EDNS record, so it carries no DNSSEC data; there is nothing to validate"
                    .to_string(),
            ),
        });
    }

    // Every zone that signed a step of the answer. Each is walked to the root.
    let mut zones: Vec<String> = Vec::new();
    // How the chain ended, when it did not end at a signed RRset.
    let mut tail: Option<ChainStatus> = None;
    let mut current = format!("{}.", qname.trim_end_matches('.'));
    let mut resolved = false;
    // A zone whose signatures use only algorithms that are not implemented
    // here. Its chain walk decides between Insecure and Bogus.
    let mut unverifiable: Option<String> = None;

    // 1. Follow the answer from the query name, one RRset at a time. At each
    // name the response holds either the queried type, which ends the chain;
    // a CNAME, signed or synthesized from a signed DNAME, which moves it to
    // another name; or nothing, which makes it a negative answer for that name. Records the chain never reaches are not
    // looked at, so a validly signed RRset for some other name proves nothing.
    for _ in 0..MAX_CHAIN_STEPS {
        let holds = |rtype: RecordType| owned_by(&answer.answers, &current, rtype).next().is_some();
        let (step, label) = if holds(qtype) {
            (qtype, qtype.to_string())
        } else if let Some(target) = cname_target(&answer.answers, &current) {
            (
                RecordType::CNAME,
                format!("CNAME {} \u{2192} {}", current, target),
            )
        } else {
            // NXDOMAIN or NODATA for this name: validate the denial-of-existence
            // proof carried in the authority section.
            match validate_denial(answer, &current, qtype, now, fetch)? {
                DenialOutcome::Proven {
                    signer,
                    mut denial_links,
                } => {
                    links.append(&mut denial_links);
                    push_zone(&mut zones, signer);
                }
                DenialOutcome::Unsigned => {
                    tail = Some(classify_unsigned(
                        &current, now, fetch, &mut links, trusted,
                    )?)
                }
                DenialOutcome::Unverifiable(zone) => {
                    push_zone(&mut zones, zone.clone());
                    unverifiable = Some(zone);
                }
                DenialOutcome::Bogus {
                    mut denial_links,
                    reason,
                } => {
                    links.append(&mut denial_links);
                    return Ok(ValidationReport {
                        links,
                        status: ChainStatus::Bogus(reason),
                    });
                }
            }
            resolved = true;
            break;
        };

        let outcome =
            match verify_answer_rrset(answer, &current, step, &label, now, fetch, &mut links)? {
                // A CNAME synthesized from a DNAME is never signed itself; the
                // DNAME that produced it is.
                Step::Unsigned if step == RecordType::CNAME => {
                    verify_dname_synthesis(answer, &current, now, fetch, &mut links)?
                        .unwrap_or(Step::Unsigned)
                }
                other => other,
            };
        match outcome {
            Step::Signed(zone) => push_zone(&mut zones, zone),
            Step::Unsigned => {
                // An unsigned RRset is legitimate only below a proven
                // unsigned delegation. Nothing past it can be trusted either
                // way.
                tail = Some(classify_unsigned(
                    &current, now, fetch, &mut links, trusted,
                )?);
                resolved = true;
                break;
            }
            Step::Unverifiable(zone) => {
                push_zone(&mut zones, zone.clone());
                unverifiable = Some(zone);
                resolved = true;
                break;
            }
            Step::Stop(status) => return Ok(ValidationReport { links, status }),
        }
        if step == qtype {
            resolved = true;
            break;
        }
        current = cname_target(&answer.answers, &current).expect("step was a CNAME");
    }
    if !resolved {
        return bogus(
            links,
            current,
            format!("CNAME chain exceeds {} steps", MAX_CHAIN_STEPS),
            "CNAME chain too long or looping",
        );
    }
    if let Some(status @ ChainStatus::Bogus(_)) = tail {
        return Ok(ValidationReport { links, status });
    }

    // 2. Walk the chain from each signing zone to the root anchors. A zone
    // that an earlier walk already verified is not walked again.
    for zone in zones {
        let report = chain_to_root(zone, now, fetch, links, trusted)?;
        links = report.links;
        if report.status != ChainStatus::Secure {
            return Ok(ValidationReport {
                links,
                status: report.status,
            });
        }
    }
    if let Some(zone) = unverifiable {
        // Every walk came back Secure, so this zone's DS names an algorithm
        // that is implemented here. A zone must sign with each algorithm its
        // DS names (RFC 4035 §2.2); the usable signatures were left out.
        return bogus(
            links,
            zone.clone(),
            "signed only with an algorithm digg does not implement, though the zone's DS names one it does",
            format!("{}: the signatures digg could verify are missing", zone),
        );
    }
    Ok(ValidationReport {
        links,
        status: tail.unwrap_or(ChainStatus::Secure),
    })
}

/// A resolver gives up on a CNAME chain well before this; it only bounds a
/// response built to loop.
const MAX_CHAIN_STEPS: usize = 16;

/// The records of one type that `owner` holds in a section.
fn owned_by<'a>(
    section: &'a [ResourceRecord],
    owner: &'a str,
    rtype: RecordType,
) -> impl Iterator<Item = &'a ResourceRecord> {
    section
        .iter()
        .filter(move |rr| rr.rtype == rtype && names_equal(&rr.name, owner))
}

fn cname_target(section: &[ResourceRecord], owner: &str) -> Option<String> {
    owned_by(section, owner, RecordType::CNAME).find_map(|rr| match &rr.rdata {
        RData::CNAME(target) => Some(target.clone()),
        _ => None,
    })
}

fn push_zone(zones: &mut Vec<String>, zone: String) {
    if !zones.iter().any(|z| names_equal(z, &zone)) {
        zones.push(zone);
    }
}

fn label_count(name: &str) -> usize {
    name.trim_end_matches('.')
        .split('.')
        .filter(|l| !l.is_empty())
        .count()
}

/// Is `name` at or below `zone`?
fn in_zone(name: &str, zone: &str) -> bool {
    common_suffix_labels(name, zone) == label_count(zone)
}

/// RFC 6672: an unsigned CNAME at `owner` stands if a signed DNAME above it
/// produces exactly that CNAME. Returns `None` when no signed DNAME covers
/// `owner`, leaving the CNAME as unsigned as it looked.
fn verify_dname_synthesis(
    answer: &DnsMessage,
    owner: &str,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
    links: &mut Vec<LinkReport>,
) -> Result<Option<Step>, DnsError> {
    let Some(cname) = cname_target(&answer.answers, owner) else {
        return Ok(None);
    };
    // A DNAME redirects the names below its owner, never the owner itself.
    let dname = answer.answers.iter().find_map(|rr| match &rr.rdata {
        RData::DNAME(target) if in_zone(owner, &rr.name) && !names_equal(owner, &rr.name) => {
            Some((rr.name.clone(), target.clone()))
        }
        _ => None,
    });
    let Some((dname_owner, dname_target)) = dname else {
        return Ok(None);
    };

    let label = format!("DNAME {} \u{2192} {}", dname_owner, dname_target);
    let zone = match verify_answer_rrset(
        answer,
        &dname_owner,
        RecordType::DNAME,
        &label,
        now,
        fetch,
        links,
    )? {
        Step::Signed(zone) => zone,
        Step::Unsigned => return Ok(None),
        stop => return Ok(Some(stop)),
    };

    // The CNAME must be the owner with the DNAME's owner swapped for its
    // target. Anything else was not synthesized from this DNAME.
    let labels: Vec<&str> = owner.trim_end_matches('.').split('.').collect();
    let prefix = labels[..labels.len() - label_count(&dname_owner)].join(".");
    let expected = format!("{}.{}", prefix, dname_target.trim_start_matches('.'));
    if !names_equal(&cname, &expected) {
        links.push(LinkReport::failed(
            zone.clone(),
            format!(
                "CNAME {} \u{2192} {} is not what the DNAME produces ({})",
                owner, cname, expected
            ),
        ));
        return Ok(Some(Step::Stop(ChainStatus::Bogus(format!(
            "{}: CNAME for {} does not match its DNAME",
            zone, owner
        )))));
    }
    links.push(LinkReport::ok(
        zone.clone(),
        format!("CNAME {} \u{2192} {} synthesized from DNAME", owner, cname),
    ));
    Ok(Some(Step::Signed(zone)))
}

enum Step {
    /// The RRset verified against this zone's DNSKEY set.
    Signed(String),
    /// The RRset carries no RRSIG.
    Unsigned,
    /// This zone signed the RRset only with algorithms that are not
    /// implemented here. Whether that makes it unsigned or bogus depends on
    /// the zone's DS, which the chain walk reads.
    Unverifiable(String),
    /// Validation ends here with this status.
    Stop(ChainStatus),
}

/// Verify the `rtype` RRset that `owner` holds in the answer section against
/// the DNSKEY set of the zone that signed it. `label` names the RRset in the
/// report.
fn verify_answer_rrset(
    answer: &DnsMessage,
    owner: &str,
    rtype: RecordType,
    label: &str,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
    links: &mut Vec<LinkReport>,
) -> Result<Step, DnsError> {
    let rrset: Vec<&ResourceRecord> = owned_by(&answer.answers, owner, rtype).collect();
    let rrsigs: Vec<&ResourceRecord> = rrsigs_covering(&answer.answers, rtype)
        .filter(|rr| names_equal(&rr.name, owner))
        .collect();
    let Some(RData::RRSIG { signer, .. }) = rrsigs.first().map(|rr| &rr.rdata) else {
        return Ok(Step::Unsigned);
    };
    let zone = signer.clone();

    // RFC 4035 §5.3.1: the signer must be the zone that contains the RRset.
    // Without this, any zone with a valid chain of its own could sign for a
    // name it has no authority over.
    if !in_zone(owner, &zone) {
        links.push(LinkReport::failed(
            zone.clone(),
            format!(
                "{} RRSIG is signed by a zone that does not contain {}",
                label, owner
            ),
        ));
        return Ok(Step::Stop(ChainStatus::Bogus(format!(
            "{}: not a parent of {}, so it cannot sign for it",
            zone, owner
        ))));
    }

    let dnskey_msg = fetch(&zone, RecordType::DNSKEY)?;
    let dnskeys = records_of(&dnskey_msg.answers, RecordType::DNSKEY);

    // A zone mid-rollover signs each RRset more than once; one good signature
    // is enough.
    let mut verified = None;
    let mut failure = String::new();
    for sig in &rrsigs {
        let RData::RRSIG {
            signer: sig_signer,
            labels,
            ..
        } = &sig.rdata
        else {
            continue;
        };
        if !names_equal(sig_signer, &zone) {
            continue;
        }
        if *labels as usize > rrsig_label_count(owner) {
            failure = "RRSIG label count exceeds the owner name's".to_string();
            continue;
        }
        match verify_rrsig(&rrset, sig, &dnskeys, now) {
            Ok(tag) => {
                verified = Some((tag, *labels));
                break;
            }
            Err(e) => failure = e,
        }
    }
    if verified.is_none()
        && all_unsupported(rrsigs.iter().copied().filter(
            |rr| matches!(&rr.rdata, RData::RRSIG { signer, .. } if names_equal(signer, &zone)),
        ))
    {
        return Ok(Step::Unverifiable(zone));
    }
    let Some((tag, labels)) = verified else {
        links.push(LinkReport::failed(
            zone.clone(),
            format!("{} RRSIG failed: {}", label, failure),
        ));
        return Ok(Step::Stop(ChainStatus::Bogus(format!(
            "{}: answer signature invalid: {}",
            zone, failure
        ))));
    };
    links.push(LinkReport::ok(
        zone.clone(),
        format!("{} RRSIG verified (key {})", label, tag),
    ));

    // The signature above also verifies for an RRset synthesized from a
    // wildcard, because build_signed_data rebuilds the wildcard owner. That
    // says the wildcard's data is genuine, not that the wildcard applies: the
    // same records replayed for a name that exists in its own right would
    // verify too. The answer must carry proof that the name does not exist.
    match prove_wildcard_expansion(&answer.authority, owner, labels, &zone, &dnskeys, now) {
        WildcardProof::NotExpanded => {}
        WildcardProof::Proven(detail) => links.push(LinkReport::ok(zone.clone(), detail)),
        WildcardProof::OptOut(detail) => {
            links.push(LinkReport::ok(zone.clone(), detail));
            return Ok(Step::Stop(ChainStatus::Insecure(format!(
                "{}: wildcard expansion rests on an opt-out NSEC3, which does not rule out an unsigned delegation",
                zone
            ))));
        }
        WildcardProof::Unproven(reason) => {
            links.push(LinkReport::failed(
                zone.clone(),
                format!("wildcard expansion not proven: {}", reason),
            ));
            return Ok(Step::Stop(ChainStatus::Bogus(format!(
                "{}: {}",
                zone, reason
            ))));
        }
    }
    Ok(Step::Signed(zone))
}

/// Warm the fetch cache with every record the walk below is about to ask for,
/// in one parallel round instead of one blocking round trip at a time.
///
/// The zones are predictable: the chain runs from `start` up through its
/// parents to the root, and each non-root zone needs its DNSKEY and its DS.
/// This only predicts *which* records to ask for - nothing is trusted, and the
/// walk still fetches, verifies and decides exactly as before. A wrong guess
/// costs one unused response, because the walk misses the cache and fetches
/// for real; the chain walk prefers the DS RRSIG's signer over the derived
/// parent name, so that can happen for unconventional delegations.
///
/// The cost is queries for zones the walk may never reach, when a chain ends
/// early at an unsigned delegation or turns out bogus. That is bounded by the
/// label count of the name being validated.
fn prefetch_chain(
    start: &str,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
) {
    let mut wanted: Vec<(String, RecordType)> = Vec::new();
    let mut zone = start.to_string();
    loop {
        wanted.push((zone.clone(), RecordType::DNSKEY));
        if zone == "." {
            break;
        }
        wanted.push((zone.clone(), RecordType::DS));
        zone = parent_zone(&zone);
    }

    // Results are discarded: this runs purely to populate the memo in
    // validate_with, and any error here is re-encountered by the real walk,
    // which is where it gets reported.
    parallel::map(&wanted, usize::MAX, |(name, rtype)| {
        let _ = fetch(name, *rtype);
    });
}

/// Walk from `zone` up to the root, verifying each zone's DNSKEY RRset and
/// matching it against the parent's DS, until a root trust anchor or a zone in
/// `trusted`. Shared by positive-answer and denial-of-existence validation.
fn chain_to_root(
    mut zone: String,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
    mut links: Vec<LinkReport>,
    trusted: &mut Vec<String>,
) -> Result<ValidationReport, DnsError> {
    if !trusted.iter().any(|z| names_equal(z, &zone)) {
        prefetch_chain(&zone, fetch);
    }
    // Zones this walk has verified. They join `trusted` only once the walk
    // reaches the root, or a zone an earlier walk took there.
    let mut walked = Vec::new();
    loop {
        if trusted.iter().any(|z| names_equal(z, &zone)) {
            trusted.append(&mut walked);
            return Ok(ValidationReport {
                links,
                status: ChainStatus::Secure,
            });
        }
        // RFC 4035 §5.2: a zone whose DS RRset names no algorithm this
        // validator implements is treated as unsigned. That is the parent's
        // statement, so the DS must still be signed by the parent, and the
        // parent must still lead to the root.
        if zone != "." {
            let ds_msg = fetch(&zone, RecordType::DS)?;
            let ds_set = records_of(&ds_msg.answers, RecordType::DS);
            if let Some(algorithms) = unsupported_only(&ds_set) {
                let parent = match verify_ds_rrsig(&zone, &ds_msg, &ds_set, now, fetch)? {
                    DsSignature::Verified { parent, tag } => {
                        links.push(LinkReport::ok(
                            zone.clone(),
                            format!("DS RRSIG verified by {} (key {})", parent, tag),
                        ));
                        parent
                    }
                    // The parent is in the same position; its own turn decides.
                    DsSignature::Unverifiable { parent } => parent,
                    DsSignature::Invalid(e) => {
                        return bogus(
                            links,
                            zone.clone(),
                            format!("DS RRSIG failed: {}", e),
                            format!("{}: DS signature invalid: {}", zone, e),
                        );
                    }
                };
                links.push(LinkReport::ok(
                    zone.clone(),
                    format!(
                        "DS names only algorithm {}, which digg does not implement",
                        algorithms
                    ),
                ));
                let report = chain_to_root(parent, now, fetch, links, trusted)?;
                return Ok(match report.status {
                    ChainStatus::Secure => ValidationReport {
                        links: report.links,
                        status: ChainStatus::Insecure(format!(
                            "{}: signed only with algorithm {}, which digg does not implement; treated as unsigned",
                            zone, algorithms
                        )),
                    },
                    _ => report,
                });
            }
        }

        let dnskey_msg = fetch(&zone, RecordType::DNSKEY)?;
        let dnskeys = records_of(&dnskey_msg.answers, RecordType::DNSKEY);
        let dnskey_sigs: Vec<&ResourceRecord> =
            rrsigs_covering(&dnskey_msg.answers, RecordType::DNSKEY).collect();

        // 3a. DNSKEY RRset must be self-consistent (signed by a key in it).
        let self_sig = dnskey_sigs
            .iter()
            .find_map(|sig| verify_rrsig(&dnskeys, sig, &dnskeys, now).ok());
        match self_sig {
            Some(tag) => links.push(LinkReport::ok(
                zone.clone(),
                format!("DNSKEY RRset verified (KSK {})", tag),
            )),
            None => {
                let detail = if dnskey_sigs.is_empty() {
                    "DNSKEY RRset has no RRSIG".to_string()
                } else {
                    "DNSKEY RRset signature invalid".to_string()
                };
                let reason = format!("{}: {}", zone, detail);
                return bogus(links, zone.clone(), detail, reason);
            }
        }

        if zone == "." {
            // 3b. Root: DNSKEY KSK must match a built-in trust anchor.
            let matched = dnskeys.iter().any(|key| {
                ROOT_ANCHORS.iter().any(|anchor| {
                    key_tag(&key.raw_rdata) == anchor.key_tag
                        && ds_digest(".", key, 2).as_deref() == Some(anchor.digest)
                })
            });
            if matched {
                links.push(LinkReport::ok(
                    zone.clone(),
                    "root KSK matches IANA trust anchor".to_string(),
                ));
                walked.push(zone);
                trusted.append(&mut walked);
                return Ok(ValidationReport {
                    links,
                    status: ChainStatus::Secure,
                });
            }
            return bogus(
                links,
                zone.clone(),
                "root DNSKEY does not match any built-in trust anchor",
                "root trust anchor mismatch",
            );
        }

        // 3c. Parent DS must match one of this zone's keys.
        let ds_msg = fetch(&zone, RecordType::DS)?;
        let ds_set = records_of(&ds_msg.answers, RecordType::DS);
        if ds_set.is_empty() {
            // A zone with keys but no DS is an island: its signatures cannot
            // be anchored. That is only believable when the parent proves it
            // publishes no DS. Otherwise deleting the DS from a response would
            // turn any signed zone into an "unsigned" one.
            return match ds_denial(&ds_msg, &zone, now, fetch)? {
                Delegation::Unsigned { signer, detail, .. } => {
                    links.push(LinkReport::ok(zone.clone(), detail));
                    let report = chain_to_root(signer, now, fetch, links, trusted)?;
                    Ok(match report.status {
                        ChainStatus::Secure => ValidationReport {
                            links: report.links,
                            status: ChainStatus::Insecure(format!(
                                "{}: unsigned delegation, chain ends",
                                zone
                            )),
                        },
                        _ => report,
                    })
                }
                Delegation::NotACut => {
                    let detail = "no DS at parent, and the parent shows no delegation here";
                    let reason = format!("{}: {}", zone, detail);
                    bogus(links, zone.clone(), detail, reason)
                }
                Delegation::Unproven(why) => {
                    let detail = format!("no DS at parent, and {}", why);
                    let reason = format!("{}: {}", zone, detail);
                    bogus(links, zone.clone(), detail, reason)
                }
            };
        }

        let ds_match = ds_set.iter().find_map(|ds| {
            let RData::DS {
                key_tag: tag,
                digest_type,
                digest,
                ..
            } = &ds.rdata
            else {
                return None;
            };
            dnskeys.iter().find_map(|key| {
                if key_tag(&key.raw_rdata) == *tag
                    && ds_digest(&zone, key, *digest_type).as_deref() == Some(digest.as_slice())
                {
                    Some(*tag)
                } else {
                    None
                }
            })
        });
        match ds_match {
            Some(tag) => links.push(LinkReport::ok(
                zone.clone(),
                format!("DS\u{2192}DNSKEY digest verified (key {})", tag),
            )),
            None => {
                return bogus(
                    links,
                    zone.clone(),
                    "no DS digest matches any DNSKEY",
                    format!("{}: DS/DNSKEY digest mismatch", zone),
                );
            }
        }

        // 3d. The DS RRset itself must be signed by the parent zone. Without
        // that, the digest above only shows the DS and the keys agree with
        // each other, which a forger supplying both can arrange.
        let parent = match verify_ds_rrsig(&zone, &ds_msg, &ds_set, now, fetch)? {
            DsSignature::Verified { parent, tag } => {
                links.push(LinkReport::ok(
                    zone.clone(),
                    format!("DS RRSIG verified by {} (key {})", parent, tag),
                ));
                parent
            }
            DsSignature::Unverifiable { parent } => {
                // Only believable if the parent turns out to be a zone this
                // validator cannot verify at all.
                let report = chain_to_root(parent, now, fetch, links, trusted)?;
                return match report.status {
                    ChainStatus::Secure => {
                        let detail = "DS is signed only with an algorithm digg does not implement, though the parent has one it does";
                        let reason = format!("{}: {}", zone, detail);
                        bogus(report.links, zone.clone(), detail, reason)
                    }
                    _ => Ok(report),
                };
            }
            DsSignature::Invalid(e) => {
                return bogus(
                    links,
                    zone.clone(),
                    format!("DS RRSIG failed: {}", e),
                    format!("{}: DS signature invalid: {}", zone, e),
                );
            }
        };

        walked.push(std::mem::replace(&mut zone, parent));
    }
}

/// The DNSSEC signature algorithms verify_signature implements.
fn supported_algorithm(algorithm: u8) -> bool {
    matches!(algorithm, 8 | 10 | 13 | 14 | 15)
}

/// If no DS in the set can be used, because of its key algorithm or its
/// digest type, the key algorithms it names. `None` for an empty set or one
/// with a usable DS.
fn unsupported_only(ds_set: &[&ResourceRecord]) -> Option<String> {
    let mut algorithms: Vec<u8> = Vec::new();
    for ds in ds_set {
        let RData::DS {
            algorithm,
            digest_type,
            ..
        } = &ds.rdata
        else {
            continue;
        };
        if supported_algorithm(*algorithm) && matches!(digest_type, 1 | 2 | 4) {
            return None;
        }
        if !algorithms.contains(algorithm) {
            algorithms.push(*algorithm);
        }
    }
    if algorithms.is_empty() {
        return None;
    }
    let names: Vec<String> = algorithms.iter().map(|a| a.to_string()).collect();
    Some(names.join("/"))
}

/// Do all of these RRSIGs use an algorithm verify_signature lacks?
fn all_unsupported<'a>(rrsigs: impl Iterator<Item = &'a ResourceRecord>) -> bool {
    let mut any = false;
    for rr in rrsigs {
        if let RData::RRSIG { algorithm, .. } = &rr.rdata {
            if supported_algorithm(*algorithm) {
                return false;
            }
            any = true;
        }
    }
    any
}

enum DsSignature {
    Verified {
        parent: String,
        tag: u16,
    },
    /// The parent signed the DS only with algorithms that are not
    /// implemented here.
    Unverifiable {
        parent: String,
    },
    Invalid(String),
}

/// Verify the RRSIG over `zone`'s DS RRset. DS lives on the parent side of
/// the cut, so the signer must be a zone above `zone`, never `zone` itself or
/// an unrelated one.
fn verify_ds_rrsig(
    zone: &str,
    ds_msg: &DnsMessage,
    ds_set: &[&ResourceRecord],
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
) -> Result<DsSignature, DnsError> {
    let by_parent = |rr: &&ResourceRecord| -> Option<String> {
        match &rr.rdata {
            RData::RRSIG { signer, .. } if in_zone(zone, signer) && !names_equal(zone, signer) => {
                Some(signer.clone())
            }
            _ => None,
        }
    };
    let sigs: Vec<&ResourceRecord> = rrsigs_covering(&ds_msg.answers, RecordType::DS)
        .filter(|rr| names_equal(&rr.name, zone))
        .collect();
    let Some(parent) = sigs.iter().find_map(by_parent) else {
        return Ok(DsSignature::Invalid(
            "DS RRset is not signed by a parent zone".to_string(),
        ));
    };
    let sigs: Vec<&ResourceRecord> = sigs
        .into_iter()
        .filter(|rr| by_parent(rr).is_some_and(|signer| names_equal(&signer, &parent)))
        .collect();
    if all_unsupported(sigs.iter().copied()) {
        return Ok(DsSignature::Unverifiable { parent });
    }

    let parent_keys_msg = fetch(&parent, RecordType::DNSKEY)?;
    let parent_keys = records_of(&parent_keys_msg.answers, RecordType::DNSKEY);
    let mut failure = String::new();
    for sig in sigs {
        match verify_rrsig(ds_set, sig, &parent_keys, now) {
            Ok(tag) => return Ok(DsSignature::Verified { parent, tag }),
            Err(e) => failure = e,
        }
    }
    Ok(DsSignature::Invalid(failure))
}

/// For an unsigned RRset or an unsigned negative answer at `name`, decide
/// Insecure vs Bogus.
///
/// Unsigned data is legitimate only at or below an unsigned delegation, and a
/// signed parent proves that delegation: its NSEC or NSEC3 for the delegation
/// point has NS set and no DS. So walk down from the top-level domain asking
/// for DS at each name. A DS means a signed delegation; keep going. A proof
/// that the name is an unsigned delegation ends the walk as Insecure, once the
/// zone that signed the proof is itself verified to the root. A name that is
/// not a delegation is passed over. Reaching `name` without such a proof means
/// its zone is signed and the missing signatures are the problem.
///
/// A response with no DS and no proof counts for nothing: it is what a
/// resolver that strips DNSSEC records, or an attacker, would send.
fn classify_unsigned(
    name: &str,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
    links: &mut Vec<LinkReport>,
    trusted: &mut Vec<String>,
) -> Result<ChainStatus, DnsError> {
    let labels: Vec<&str> = name
        .trim_end_matches('.')
        .split('.')
        .filter(|l| !l.is_empty())
        .collect();
    let cuts: Vec<String> = (1..=labels.len())
        .map(|depth| format!("{}.", labels[labels.len() - depth..].join(".")))
        .collect();

    // Results are discarded: this only warms the memo in validate_with so the
    // walk below is one parallel round, not one round trip per label.
    parallel::map(&cuts, usize::MAX, |cut| {
        let _ = fetch(cut, RecordType::DS);
    });

    for cut in &cuts {
        let ds_msg = fetch(cut, RecordType::DS)?;
        let ds_set: Vec<&ResourceRecord> = owned_by(&ds_msg.answers, cut, RecordType::DS).collect();
        if unsupported_only(&ds_set).is_some() {
            // Signed, but with nothing this validator implements: everything
            // below is unsigned as far as it can tell. chain_to_root checks
            // that the parent really says so.
            let report = chain_to_root(cut.clone(), now, fetch, std::mem::take(links), trusted)?;
            *links = report.links;
            return Ok(report.status);
        }
        if !ds_set.is_empty() {
            continue;
        }
        match ds_denial(&ds_msg, cut, now, fetch)? {
            Delegation::Unsigned {
                signer,
                detail,
                certain,
            } => {
                links.push(LinkReport::ok(cut.clone(), detail));
                let report = chain_to_root(signer, now, fetch, std::mem::take(links), trusted)?;
                *links = report.links;
                return Ok(match report.status {
                    ChainStatus::Secure if certain => ChainStatus::Insecure(format!(
                        "{} is an unsigned delegation; answer cannot be validated",
                        cut
                    )),
                    // An opt-out span lists no unsigned delegation, so it
                    // cannot say whether this one exists.
                    ChainStatus::Secure => ChainStatus::Insecure(format!(
                        "{} has no DS and sits in an opt-out span, so it may be an unsigned delegation; answer cannot be validated",
                        cut
                    )),
                    other => other,
                });
            }
            Delegation::NotACut => {}
            Delegation::Unproven(why) => {
                links.push(LinkReport::failed(
                    cut.clone(),
                    format!("no DS, and {}", why),
                ));
                return Ok(ChainStatus::Bogus(format!(
                    "{} carries no RRSIG, and nothing proves {} is an unsigned delegation",
                    name, cut
                )));
            }
        }
    }
    Ok(ChainStatus::Bogus(format!(
        "{} is in a signed zone but carries no RRSIG",
        name
    )))
}

/// What a signed parent says about a name that has no DS.
enum Delegation {
    /// An unsigned delegation: NS without DS, or an opt-out NSEC3 span that
    /// may hold one. `signer` is the parent zone that signed the proof.
    Unsigned {
        signer: String,
        detail: String,
        /// False for an opt-out span, which shows only that there may be one.
        certain: bool,
    },
    /// The name exists in the parent zone and is not delegated.
    NotACut,
    /// No valid proof either way.
    Unproven(String),
}

/// Read the denial in a DS response for `name`: is `name` an unsigned
/// delegation, according to records its parent zone signed?
fn ds_denial(
    ds_msg: &DnsMessage,
    name: &str,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
) -> Result<Delegation, DnsError> {
    // A DS query for a name that holds a CNAME is answered by following it, so
    // the response carries the CNAME and no denial. A CNAME cannot sit at a
    // delegation point, so a validly signed one settles the question.
    let cname_sig = rrsigs_covering(&ds_msg.answers, RecordType::CNAME).find(|rr| {
        names_equal(&rr.name, name)
            && matches!(&rr.rdata, RData::RRSIG { signer, .. } if in_zone(name, signer))
    });
    if let Some(sig) = cname_sig {
        let RData::RRSIG { signer, .. } = &sig.rdata else {
            unreachable!("filtered on RRSIG above");
        };
        let cname: Vec<&ResourceRecord> =
            owned_by(&ds_msg.answers, name, RecordType::CNAME).collect();
        let keys_msg = fetch(signer, RecordType::DNSKEY)?;
        let keys = records_of(&keys_msg.answers, RecordType::DNSKEY);
        if !cname.is_empty() && verify_rrsig(&cname, sig, &keys, now).is_ok() {
            return Ok(Delegation::NotACut);
        }
    }

    // DS lives on the parent side of a cut, so the proof must come from a zone
    // above `name`. The child's own NSEC at its apex says nothing about DS.
    let signer = ds_msg
        .authority
        .iter()
        .filter_map(|rr| match &rr.rdata {
            RData::RRSIG {
                type_covered,
                signer,
                ..
            } if matches!(type_covered, RecordType::NSEC | RecordType::NSEC3)
                && in_zone(name, signer)
                && !names_equal(name, signer) =>
            {
                Some(signer)
            }
            _ => None,
        })
        .max_by_key(|signer| label_count(signer));
    let Some(signer) = signer else {
        return Ok(Delegation::Unproven(format!(
            "no parent zone signed a proof that {} has none",
            name
        )));
    };

    let dnskey_msg = fetch(signer, RecordType::DNSKEY)?;
    let dnskeys = records_of(&dnskey_msg.answers, RecordType::DNSKEY);
    let nsecs = verified_denial_records(&ds_msg.authority, RecordType::NSEC, signer, &dnskeys, now);
    let nsec3s =
        verified_denial_records(&ds_msg.authority, RecordType::NSEC3, signer, &dnskeys, now);
    Ok(delegation_proof(&nsecs, &nsec3s, name, signer))
}

/// The proof itself, over denial records already known to be validly signed
/// by `signer`.
fn delegation_proof(
    nsecs: &[&ResourceRecord],
    nsec3s: &[&ResourceRecord],
    name: &str,
    signer: &str,
) -> Delegation {
    // The type bitmap of the NSEC/NSEC3 that matches `name` settles it.
    let from_bitmap = |types: &[RecordType], kind: &str| {
        if types.contains(&RecordType::DS) {
            Delegation::Unproven(format!("{} at {} says a DS exists", kind, name))
        } else if types.contains(&RecordType::NS) && !types.contains(&RecordType::SOA) {
            Delegation::Unsigned {
                signer: signer.to_string(),
                detail: format!(
                    "unsigned delegation proven: {} by {} has NS and no DS",
                    kind, signer
                ),
                certain: true,
            }
        } else {
            Delegation::NotACut
        }
    };

    for rr in nsecs {
        let RData::NSEC {
            next_domain,
            type_bitmaps,
        } = &rr.rdata
        else {
            continue;
        };
        if names_equal(&rr.name, name) {
            return from_bitmap(type_bitmaps, "NSEC");
        }
        if nsec_covers(rr, name) {
            // Names exist below `name`, so it is an empty non-terminal: it
            // exists, owns nothing, and is not a delegation.
            if in_zone(next_domain, name) {
                return Delegation::NotACut;
            }
            return Delegation::Unproven(format!("{} does not exist in {}", name, signer));
        }
    }

    for rr in nsec3s {
        let RData::NSEC3 {
            iterations,
            salt,
            type_bitmaps,
            ..
        } = &rr.rdata
        else {
            continue;
        };
        if nsec3_hash(name, *iterations, salt).is_some_and(|h| nsec3_matches(rr, &h)) {
            return from_bitmap(type_bitmaps, "NSEC3");
        }
    }
    if !nsec3s.is_empty() {
        return match nsec3_closest_encloser(nsec3s, name, signer) {
            // RFC 5155 §6: an opt-out span may hold unsigned delegations
            // that have no NSEC3 of their own.
            Ok(proof) if proof.opt_out => Delegation::Unsigned {
                signer: signer.to_string(),
                detail: format!(
                    "unsigned delegation possible: opt-out NSEC3 by {} covers it",
                    signer
                ),
                certain: false,
            },
            Ok(_) => Delegation::Unproven(format!("{} does not exist in {}", name, signer)),
            Err(why) => Delegation::Unproven(why),
        };
    }
    Delegation::Unproven(format!(
        "no signed NSEC/NSEC3 from {} proves that {} has none",
        signer, name
    ))
}

fn parent_zone(zone: &str) -> String {
    match zone.trim_end_matches('.').split_once('.') {
        Some((_, rest)) => format!("{}.", rest),
        None => ".".to_string(),
    }
}

/// RFC 4034 Appendix B key tag over the raw DNSKEY RDATA.
pub fn key_tag(dnskey_rdata: &[u8]) -> u16 {
    let mut acc: u32 = 0;
    for (i, &b) in dnskey_rdata.iter().enumerate() {
        if i % 2 == 0 {
            acc += (b as u32) << 8;
        } else {
            acc += b as u32;
        }
    }
    acc += (acc >> 16) & 0xFFFF;
    (acc & 0xFFFF) as u16
}

/// DS digest of owner || DNSKEY RDATA. digest_type: 1=SHA-1, 2=SHA-256, 4=SHA-384.
fn ds_digest(owner: &str, dnskey: &ResourceRecord, digest_type: u8) -> Option<Vec<u8>> {
    let algorithm = match digest_type {
        1 => &digest::SHA1_FOR_LEGACY_USE_ONLY,
        2 => &digest::SHA256,
        4 => &digest::SHA384,
        _ => return None,
    };
    let mut data = canonical_name(owner).ok()?;
    data.extend_from_slice(&dnskey.raw_rdata);
    Some(digest::digest(algorithm, &data).as_ref().to_vec())
}

fn canonical_name(name: &str) -> Result<Vec<u8>, DnsError> {
    encode_name(&name.to_lowercase())
}

/// Canonical RDATA per RFC 4034 §6.2: embedded names in the listed types
/// are lowercased and uncompressed (re-encoded from the parsed form);
/// everything else is the raw wire bytes.
fn canonical_rdata(rr: &ResourceRecord) -> Result<Vec<u8>, DnsError> {
    match &rr.rdata {
        RData::NS(name) | RData::CNAME(name) | RData::PTR(name) | RData::DNAME(name) => {
            canonical_name(name)
        }
        RData::MX {
            preference,
            exchange,
        } => {
            let mut buf = preference.to_be_bytes().to_vec();
            buf.extend(canonical_name(exchange)?);
            Ok(buf)
        }
        RData::SRV {
            priority,
            weight,
            port,
            target,
        } => {
            let mut buf = Vec::new();
            buf.extend_from_slice(&priority.to_be_bytes());
            buf.extend_from_slice(&weight.to_be_bytes());
            buf.extend_from_slice(&port.to_be_bytes());
            buf.extend(canonical_name(target)?);
            Ok(buf)
        }
        RData::SOA {
            mname,
            rname,
            serial,
            refresh,
            retry,
            expire,
            minimum,
        } => {
            let mut buf = canonical_name(mname)?;
            buf.extend(canonical_name(rname)?);
            for v in [serial, refresh, retry, expire, minimum] {
                buf.extend_from_slice(&v.to_be_bytes());
            }
            Ok(buf)
        }
        _ => Ok(rr.raw_rdata.clone()),
    }
}

/// Verify one RRSIG over an RRset with a DNSKEY set. Returns the key tag
/// of the validating key.
pub fn verify_rrsig(
    rrset: &[&ResourceRecord],
    rrsig: &ResourceRecord,
    dnskeys: &[&ResourceRecord],
    now: u32,
) -> Result<u16, String> {
    // Only the fields this function reasons about; build_signed_data reads
    // the rest of the RRSIG itself.
    let RData::RRSIG {
        algorithm,
        expiration,
        inception,
        key_tag: sig_tag,
        signature,
        ..
    } = &rrsig.rdata
    else {
        return Err("not an RRSIG record".to_string());
    };

    // RFC 1982 serial-number comparison keeps this correct across the
    // 2038/2106 wrap; a plain range check is fine for current dates.
    if now < *inception {
        return Err(format!("signature not yet valid (inception {})", inception));
    }
    if now > *expiration {
        return Err(format!("signature expired at {}", expiration));
    }

    let signed = build_signed_data(&rrsig.rdata, rrset).map_err(|e| e.to_string())?;

    let key = dnskeys
        .iter()
        .find(|k| {
            key_tag(&k.raw_rdata) == *sig_tag
                && matches!(&k.rdata, RData::DNSKEY { algorithm: a, .. } if a == algorithm)
        })
        .ok_or_else(|| format!("no DNSKEY with tag {} algorithm {}", sig_tag, algorithm))?;
    let RData::DNSKEY { public_key, .. } = &key.rdata else {
        return Err("matched record is not a DNSKEY".to_string());
    };

    verify_signature(*algorithm, public_key, &signed, signature)?;
    Ok(*sig_tag)
}

/// The bytes an RRSIG is computed over: the RRSIG RDATA minus its signature
/// field, followed by the canonical RRset (RFC 4034 s3.1.8.1).
fn build_signed_data(rrsig: &RData, rrset: &[&ResourceRecord]) -> Result<Vec<u8>, DnsError> {
    let RData::RRSIG {
        type_covered,
        algorithm,
        labels,
        original_ttl,
        expiration,
        inception,
        key_tag,
        signer,
        ..
    } = rrsig
    else {
        return Err(DnsError::Protocol("not an RRSIG record".into()));
    };

    // RRSIG RDATA with the signature field removed.
    let mut data = Vec::new();
    data.extend_from_slice(&type_covered.to_u16().to_be_bytes());
    data.push(*algorithm);
    data.push(*labels);
    data.extend_from_slice(&original_ttl.to_be_bytes());
    data.extend_from_slice(&expiration.to_be_bytes());
    data.extend_from_slice(&inception.to_be_bytes());
    data.extend_from_slice(&key_tag.to_be_bytes());
    data.extend(canonical_name(signer)?);

    // Canonical RRset: sorted by canonical RDATA, owner lowercased and
    // wildcard-adjusted to the RRSIG label count, TTL = original TTL.
    let mut entries: Vec<(Vec<u8>, &&ResourceRecord)> = rrset
        .iter()
        .map(|rr| canonical_rdata(rr).map(|c| (c, rr)))
        .collect::<Result<_, _>>()?;
    entries.sort_by(|a, b| a.0.cmp(&b.0));
    entries.dedup_by(|a, b| a.0 == b.0);

    for (canon, rr) in entries {
        let owner = wildcard_owner(&rr.name, *labels);
        data.extend(canonical_name(&owner)?);
        data.extend_from_slice(&rr.rtype.to_u16().to_be_bytes());
        data.extend_from_slice(&rr.rclass.to_u16().to_be_bytes());
        data.extend_from_slice(&original_ttl.to_be_bytes());
        data.extend_from_slice(&(canon.len() as u16).to_be_bytes());
        data.extend_from_slice(&canon);
    }
    Ok(data)
}

/// RFC 4035 §5.3.2: when the RRSIG label count is smaller than the owner's,
/// the RRset was synthesized from a wildcard — validate against "*.<suffix>".
fn wildcard_owner(name: &str, labels: u8) -> String {
    let trimmed = name.trim_end_matches('.');
    if trimmed.is_empty() {
        // Root owner: zero labels by definition, never wildcard-adjusted.
        return ".".to_string();
    }
    let parts: Vec<&str> = trimmed.split('.').collect();
    if parts.len() > labels as usize {
        let suffix = &parts[parts.len() - labels as usize..];
        format!("*.{}.", suffix.join("."))
    } else {
        name.to_string()
    }
}

fn verify_signature(
    algorithm: u8,
    public_key: &[u8],
    signed: &[u8],
    sig: &[u8],
) -> Result<(), String> {
    match algorithm {
        8 | 10 => {
            // RSA/SHA-256 (8) or RSA/SHA-512 (10): DNSKEY holds explen/exp/mod.
            let der = rsa_dnskey_to_der(public_key).ok_or("malformed RSA DNSKEY")?;
            let alg: &dyn signature::VerificationAlgorithm = if algorithm == 8 {
                &signature::RSA_PKCS1_1024_8192_SHA256_FOR_LEGACY_USE_ONLY
            } else {
                &signature::RSA_PKCS1_2048_8192_SHA512
            };
            signature::UnparsedPublicKey::new(alg, &der)
                .verify(signed, sig)
                .map_err(|_| "RSA signature verification failed".to_string())
        }
        13 | 14 => {
            // ECDSA P-256/SHA-256 or P-384/SHA-384: key is raw x||y.
            let mut sec1 = vec![0x04];
            sec1.extend_from_slice(public_key);
            let alg: &dyn signature::VerificationAlgorithm = if algorithm == 13 {
                &signature::ECDSA_P256_SHA256_FIXED
            } else {
                &signature::ECDSA_P384_SHA384_FIXED
            };
            signature::UnparsedPublicKey::new(alg, &sec1)
                .verify(signed, sig)
                .map_err(|_| "ECDSA signature verification failed".to_string())
        }
        15 => signature::UnparsedPublicKey::new(&signature::ED25519, public_key)
            .verify(signed, sig)
            .map_err(|_| "Ed25519 signature verification failed".to_string()),
        other => Err(format!("unsupported DNSSEC algorithm {}", other)),
    }
}

/// Convert the DNSKEY RSA wire format (RFC 3110: explen, exponent, modulus)
/// to a DER RSAPublicKey (SEQUENCE { modulus, exponent }).
fn rsa_dnskey_to_der(key: &[u8]) -> Option<Vec<u8>> {
    if key.is_empty() {
        return None;
    }
    let (exp, modulus) = if key[0] != 0 {
        let len = key[0] as usize;
        (key.get(1..1 + len)?, key.get(1 + len..)?)
    } else {
        let len = u16::from_be_bytes([*key.get(1)?, *key.get(2)?]) as usize;
        (key.get(3..3 + len)?, key.get(3 + len..)?)
    };

    fn der_integer(bytes: &[u8]) -> Vec<u8> {
        let mut body = bytes.to_vec();
        if body.first().is_some_and(|b| b & 0x80 != 0) {
            body.insert(0, 0);
        }
        let mut out = vec![0x02];
        out.extend(der_len(body.len()));
        out.extend(body);
        out
    }
    fn der_len(len: usize) -> Vec<u8> {
        if len < 128 {
            vec![len as u8]
        } else {
            let bytes: Vec<u8> = len
                .to_be_bytes()
                .iter()
                .copied()
                .skip_while(|&b| b == 0)
                .collect();
            let mut out = vec![0x80 | bytes.len() as u8];
            out.extend(bytes);
            out
        }
    }

    let mut body = der_integer(modulus);
    body.extend(der_integer(exp));
    let mut der = vec![0x30];
    der.extend(der_len(body.len()));
    der.extend(body);
    Some(der)
}

// === Denial of existence (RFC 4035 §5.4, RFC 5155 §8) ===

enum DenialOutcome {
    /// The negative answer is cryptographically proven; `signer` is the zone
    /// whose DNSKEY signed the NSEC/NSEC3 records (chain-walked to root next).
    Proven {
        signer: String,
        denial_links: Vec<LinkReport>,
    },
    /// No signed denial records for the name. Whether that is legitimate is
    /// for classify_unsigned to decide.
    Unsigned,
    /// The zone signed its denial only with algorithms that are not
    /// implemented here; see Step::Unverifiable.
    Unverifiable(String),
    /// Denial records present but a signature failed or the proof does not
    /// cover the query. Never let this fall through to Secure.
    Bogus {
        denial_links: Vec<LinkReport>,
        reason: String,
    },
}

fn validate_denial(
    answer: &DnsMessage,
    qname: &str,
    qtype: RecordType,
    now: u32,
    fetch: &(dyn Fn(&str, RecordType) -> Result<DnsMessage, DnsError> + Sync),
) -> Result<DenialOutcome, DnsError> {
    let nsec_recs = records_of(&answer.authority, RecordType::NSEC);
    let nsec3_recs = records_of(&answer.authority, RecordType::NSEC3);

    if nsec_recs.is_empty() && nsec3_recs.is_empty() {
        return Ok(DenialOutcome::Unsigned);
    }

    // The zone that can deny `qname` is one that contains it. After a CNAME
    // chain the authority section may also hold proofs from other zones, such
    // as the wildcard proof for an earlier step, and a zone outside the name's
    // own tree has no say over it.
    let signers: Vec<(&String, RecordType)> = answer
        .authority
        .iter()
        .filter_map(|rr| match &rr.rdata {
            RData::RRSIG {
                type_covered,
                signer,
                ..
            } if matches!(type_covered, RecordType::NSEC | RecordType::NSEC3) => {
                Some((signer, *type_covered))
            }
            _ => None,
        })
        .collect();
    if signers.is_empty() {
        let denial_type = if nsec3_recs.is_empty() {
            RecordType::NSEC
        } else {
            RecordType::NSEC3
        };
        return Ok(DenialOutcome::Bogus {
            denial_links: Vec::new(),
            reason: format!("{} records present but unsigned", denial_type),
        });
    }
    let Some((signer, denial_type)) = signers
        .into_iter()
        .filter(|(signer, _)| in_zone(qname, signer))
        .max_by_key(|(signer, _)| label_count(signer))
    else {
        return Ok(DenialOutcome::Unsigned);
    };
    let signer = signer.clone();
    if all_unsupported(answer.authority.iter().filter(|rr| {
        matches!(&rr.rdata, RData::RRSIG { type_covered, signer: s, .. }
            if *type_covered == denial_type && names_equal(s, &signer))
    })) {
        return Ok(DenialOutcome::Unverifiable(signer));
    }

    // Fetch the signer's DNSKEY and verify every denial RRSIG (NSEC/NSEC3 and
    // the SOA) against it. Group records by owner+type so each RRset verifies.
    let dnskey_msg = fetch(&signer, RecordType::DNSKEY)?;
    let dnskeys = records_of(&dnskey_msg.answers, RecordType::DNSKEY);

    let mut denial_links = Vec::new();
    if let Err(reason) = verify_denial_signatures(&answer.authority, &signer, &dnskeys, now) {
        denial_links.push(LinkReport::failed(
            signer.clone(),
            format!("denial RRSIG failed: {}", reason),
        ));
        return Ok(DenialOutcome::Bogus {
            denial_links,
            reason: format!("{}: denial signature invalid: {}", signer, reason),
        });
    }

    // The same proof shape serves two answers. With NXDOMAIN the name does
    // not exist; with NOERROR it has no record of its own and the answer came
    // from a wildcard or an empty non-terminal, which is NODATA.
    let nxdomain = answer.header.rcode == Rcode::NxDomain;

    // Signatures are valid; now the cover proof, over only the records that
    // are individually signed by this zone and not wildcard-expanded. The
    // check above passes as soon as one RRset verifies, which an unsigned or
    // replayed NSEC riding along with a genuine SOA would satisfy.
    let nsec_recs =
        verified_denial_records(&answer.authority, RecordType::NSEC, &signer, &dnskeys, now);
    let nsec3_recs =
        verified_denial_records(&answer.authority, RecordType::NSEC3, &signer, &dnskeys, now);
    // The records may be the parent's proof that an ancestor of qname is an
    // unsigned delegation, sent because the answer continues in a zone the
    // parent does not sign. Then there is nothing here to prove about qname
    // itself, and classify_unsigned makes the call with its own DS lookups.
    let qlabels: Vec<&str> = qname
        .trim_end_matches('.')
        .split('.')
        .filter(|l| !l.is_empty())
        .collect();
    for depth in (label_count(&signer) + 1)..=qlabels.len() {
        let ancestor = format!("{}.", qlabels[qlabels.len() - depth..].join("."));
        if matches!(
            delegation_proof(&nsec_recs, &nsec3_recs, &ancestor, &signer),
            Delegation::Unsigned { certain: true, .. }
        ) {
            return Ok(DenialOutcome::Unsigned);
        }
    }

    let prove =
        |nsecs: &[&ResourceRecord], nsec3s: &[&ResourceRecord], ask: &mut Option<String>| {
            if !nsec3s.is_empty() {
                prove_nsec3(nsec3s, qname, &signer, qtype, nxdomain, ask)
            } else if !nsecs.is_empty() {
                prove_nsec(nsecs, qname, qtype, nxdomain, ask).map(Some)
            } else {
                Err(format!("no validly signed {} record", denial_type))
            }
        };
    let mut ask = None;
    let mut outcome = prove(&nsec_recs, &nsec3_recs, &mut ask);

    // Some resolvers answer with the record that covers qname and leave out
    // the one for the wildcard at the closest encloser, which RFC 4035 §3.1.3
    // asks them to include. The proof is incomplete without it, and assuming
    // the best would let a wildcard answer be replayed as a denial. So ask for
    // the wildcard's own records and prove again with both sets. They are
    // verified like any others; nothing is taken on the resolver's word.
    let wildcard_msg;
    if let (Err(_), Some(wildcard)) = (&outcome, ask.take()) {
        wildcard_msg = fetch(&wildcard, qtype)?;
        if owned_by(&wildcard_msg.answers, &wildcard, qtype)
            .next()
            .is_none()
        {
            let mut nsecs = nsec_recs.clone();
            nsecs.extend(verified_denial_records(
                &wildcard_msg.authority,
                RecordType::NSEC,
                &signer,
                &dnskeys,
                now,
            ));
            let mut nsec3s = nsec3_recs.clone();
            nsec3s.extend(verified_denial_records(
                &wildcard_msg.authority,
                RecordType::NSEC3,
                &signer,
                &dnskeys,
                now,
            ));
            outcome = prove(&nsecs, &nsec3s, &mut None);
        }
    }

    let proven = match outcome {
        Ok(Some(detail)) => Ok(detail),
        // Validly signed, yet no proof: an opt-out span. The answer is as good
        // as unsigned, and classify_unsigned reads the same span to say so.
        Ok(None) => return Ok(DenialOutcome::Unsigned),
        Err(reason) => Err(reason),
    };

    match proven {
        Ok(detail) => {
            denial_links.push(LinkReport::ok(signer.clone(), detail));
            Ok(DenialOutcome::Proven {
                signer,
                denial_links,
            })
        }
        Err(reason) => {
            denial_links.push(LinkReport::failed(
                signer.clone(),
                format!("denial not proven: {}", reason),
            ));
            Ok(DenialOutcome::Bogus {
                denial_links,
                reason: format!("{}: {}", signer, reason),
            })
        }
    }
}

/// Verify the RRSIG over every NSEC/NSEC3/SOA RRset that `zone` signed in the
/// authority section.
fn verify_denial_signatures(
    authority: &[ResourceRecord],
    zone: &str,
    dnskeys: &[&ResourceRecord],
    now: u32,
) -> Result<(), String> {
    let mut verified_any = false;
    for rr in authority {
        let RData::RRSIG {
            type_covered,
            signer,
            ..
        } = &rr.rdata
        else {
            continue;
        };
        if !names_equal(signer, zone) {
            continue;
        }
        // The RRset this RRSIG covers: same owner name and covered type.
        let covered: Vec<&ResourceRecord> = authority
            .iter()
            .filter(|c| c.rtype == *type_covered && names_equal(&c.name, &rr.name))
            .collect();
        if covered.is_empty() {
            continue;
        }
        verify_rrsig(&covered, rr, dnskeys, now)?;
        verified_any = true;
    }
    if verified_any {
        Ok(())
    } else {
        Err("no denial RRSIG could be verified".to_string())
    }
}

/// Compare two domain names ignoring case and any trailing root dot.
fn names_equal(a: &str, b: &str) -> bool {
    a.trim_end_matches('.')
        .eq_ignore_ascii_case(b.trim_end_matches('.'))
}

/// RFC 4034 §6.1 canonical name ordering: compare label sequences from the
/// rightmost label, each label as a lowercased octet string.
fn canonical_name_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    let la: Vec<String> = a
        .trim_end_matches('.')
        .split('.')
        .filter(|s| !s.is_empty())
        .map(|s| s.to_lowercase())
        .rev()
        .collect();
    let lb: Vec<String> = b
        .trim_end_matches('.')
        .split('.')
        .filter(|s| !s.is_empty())
        .map(|s| s.to_lowercase())
        .rev()
        .collect();
    for (x, y) in la.iter().zip(lb.iter()) {
        // Label octets compare bytewise.
        match x.as_bytes().cmp(y.as_bytes()) {
            std::cmp::Ordering::Equal => {}
            other => return other,
        }
    }
    la.len().cmp(&lb.len())
}

/// Prove NXDOMAIN or NODATA from NSEC records. When the proof fails only
/// because nothing in `nsecs` speaks for the wildcard at the closest encloser,
/// `ask` is set to that wildcard's name: its own records would settle it.
fn prove_nsec(
    nsecs: &[&ResourceRecord],
    qname: &str,
    qtype: RecordType,
    nxdomain: bool,
    ask: &mut Option<String>,
) -> Result<String, String> {
    // NODATA: an NSEC whose owner is exactly qname, with qtype absent from its
    // type bitmap (and no CNAME, which would have been followed).
    for rr in nsecs {
        if names_equal(&rr.name, qname) {
            if let RData::NSEC { type_bitmaps, .. } = &rr.rdata {
                if type_bitmaps.contains(&qtype) {
                    return Err(format!("NSEC at {} asserts {} exists", qname, qtype));
                }
                if type_bitmaps.contains(&RecordType::CNAME) {
                    return Err("NSEC indicates a CNAME that should have been followed".to_string());
                }
                return Ok(format!("NODATA proven: NSEC at {} lacks {}", qname, qtype));
            }
        }
    }

    // Otherwise an NSEC whose range (owner, next_domain) strictly covers qname
    // shows that qname has no record of its own.
    let Some((cover, next_domain)) = nsecs.iter().find_map(|rr| match &rr.rdata {
        RData::NSEC { next_domain, .. } if nsec_covers(rr, qname) => Some((rr, next_domain)),
        _ => None,
    }) else {
        return Err("no NSEC covers the query name".to_string());
    };
    let range = format!("NSEC {} < {} < {}", cover.name, qname, next_domain);

    // A name below qname exists, so qname is an empty non-terminal: it exists
    // and owns nothing.
    if in_zone(next_domain, qname) {
        return if nxdomain {
            Err(format!("{} exists as an empty non-terminal", qname))
        } else {
            Ok(format!(
                "NODATA proven: {} is an empty non-terminal: {}",
                qname, range
            ))
        };
    }

    // That is half of the proof. A wildcard at the closest encloser would
    // answer for qname, so the response must account for it as well (RFC 4035
    // §5.4): show there is none for NXDOMAIN, or show the one there lacks the
    // type for NODATA. Without this, the covering NSEC from a genuine wildcard
    // answer could be replayed alone to deny a name the wildcard serves.
    let depth =
        common_suffix_labels(qname, &cover.name).max(common_suffix_labels(qname, next_domain));
    let labels: Vec<&str> = qname.trim_end_matches('.').split('.').collect();
    let encloser = labels[labels.len() - depth..].join(".");
    let wildcard = format!("*.{}.", encloser).replace("..", ".");
    let at_wildcard = nsecs.iter().find(|rr| names_equal(&rr.name, &wildcard));

    if nxdomain {
        if at_wildcard.is_some() {
            return Err(format!("wildcard {} exists and would answer", wildcard));
        }
        if !nsecs.iter().any(|rr| nsec_covers(rr, &wildcard)) {
            *ask = Some(wildcard.clone());
            return Err(format!("wildcard {} is not denied", wildcard));
        }
        return Ok(format!("NXDOMAIN proven: {}, no wildcard", range));
    }
    let Some(RData::NSEC { type_bitmaps, .. }) = at_wildcard.map(|rr| &rr.rdata) else {
        *ask = Some(wildcard.clone());
        return Err(format!(
            "{} has no record of its own, and no NSEC shows what wildcard {} holds",
            qname, wildcard
        ));
    };
    if type_bitmaps.contains(&qtype) || type_bitmaps.contains(&RecordType::CNAME) {
        return Err(format!("wildcard {} would answer {}", wildcard, qtype));
    }
    Ok(format!(
        "NODATA proven: {} has no record of its own and wildcard {} lacks {}: {}",
        qname, wildcard, qtype, range
    ))
}

/// Does this NSEC's range strictly cover `name` (owner < name < next_domain)?
fn nsec_covers(rr: &ResourceRecord, name: &str) -> bool {
    let RData::NSEC { next_domain, .. } = &rr.rdata else {
        return false;
    };
    use std::cmp::Ordering;
    let owner_vs_name = canonical_name_cmp(&rr.name, name);
    let name_vs_next = canonical_name_cmp(name, next_domain);
    if canonical_name_cmp(&rr.name, next_domain) == Ordering::Less {
        owner_vs_name == Ordering::Less && name_vs_next == Ordering::Less
    } else {
        // Last NSEC wraps past the apex: covers anything after owner.
        owner_vs_name == Ordering::Less || name_vs_next == Ordering::Less
    }
}

/// The SHA-1 NSEC3 hash of a name (RFC 5155 §5): H = SHA1(name || salt),
/// then H = SHA1(H || salt) `iterations` more times.
fn nsec3_hash(name: &str, iterations: u16, salt: &[u8]) -> Option<Vec<u8>> {
    let mut data = canonical_name(name).ok()?;
    data.extend_from_slice(salt);
    let mut hash = digest::digest(&digest::SHA1_FOR_LEGACY_USE_ONLY, &data)
        .as_ref()
        .to_vec();
    for _ in 0..iterations {
        let mut round = hash.clone();
        round.extend_from_slice(salt);
        hash = digest::digest(&digest::SHA1_FOR_LEGACY_USE_ONLY, &round)
            .as_ref()
            .to_vec();
    }
    Some(hash)
}

/// Decode a base32hex label (the NSEC3 owner's first label) to raw bytes.
fn base32hex_decode(label: &str) -> Option<Vec<u8>> {
    let mut bits = 0u32;
    let mut nbits = 0u32;
    let mut out = Vec::new();
    for c in label.bytes() {
        let v = match c {
            b'0'..=b'9' => c - b'0',
            b'A'..=b'V' => c - b'A' + 10,
            b'a'..=b'v' => c - b'a' + 10,
            _ => return None,
        } as u32;
        bits = (bits << 5) | v;
        nbits += 5;
        if nbits >= 8 {
            nbits -= 8;
            out.push((bits >> nbits) as u8);
        }
    }
    Some(out)
}

/// The owner hash of an NSEC3 record: its first label, base32hex-decoded.
fn nsec3_owner_hash(rr: &ResourceRecord) -> Option<Vec<u8>> {
    let first = rr.name.split('.').next()?;
    base32hex_decode(first)
}

/// Does this NSEC3 cover `hash` (owner_hash < hash < next_hash, circular)?
fn nsec3_covers(rr: &ResourceRecord, hash: &[u8]) -> bool {
    let (Some(owner), RData::NSEC3 { next_hashed, .. }) = (nsec3_owner_hash(rr), &rr.rdata) else {
        return false;
    };
    use std::cmp::Ordering;
    match owner.as_slice().cmp(next_hashed.as_slice()) {
        Ordering::Less => owner.as_slice() < hash && hash < next_hashed.as_slice(),
        // The zone's last NSEC3 wraps around the ordering.
        _ => hash > owner.as_slice() || hash < next_hashed.as_slice(),
    }
}

fn nsec3_matches(rr: &ResourceRecord, hash: &[u8]) -> bool {
    nsec3_owner_hash(rr).as_deref() == Some(hash)
}

/// Prove NXDOMAIN or NODATA from NSEC3 records (RFC 5155 §8.4-8.7).
/// `Ok(None)` means the records are genuine but prove nothing: the name falls
/// in an opt-out span, where an unsigned delegation may exist unlisted.
fn prove_nsec3(
    nsec3s: &[&ResourceRecord],
    qname: &str,
    zone: &str,
    qtype: RecordType,
    nxdomain: bool,
    ask: &mut Option<String>,
) -> Result<Option<String>, String> {
    let (iterations, salt) = match &nsec3s[0].rdata {
        RData::NSEC3 {
            iterations, salt, ..
        } => (*iterations, salt.clone()),
        _ => return Err("not an NSEC3 record".to_string()),
    };
    let hash = |name: &str| nsec3_hash(name, iterations, &salt);

    // NODATA: an NSEC3 whose owner hash equals H(qname), qtype absent.
    if let Some(qhash) = hash(qname) {
        for rr in nsec3s {
            if nsec3_matches(rr, &qhash) {
                if let RData::NSEC3 { type_bitmaps, .. } = &rr.rdata {
                    if type_bitmaps.contains(&qtype) {
                        return Err(format!("NSEC3 asserts {} exists", qtype));
                    }
                    return Ok(Some(format!(
                        "NODATA proven: NSEC3 for {} lacks {}",
                        qname, qtype
                    )));
                }
            }
        }
    }

    // Otherwise the closest-encloser proof shows qname has no record of its
    // own, and the wildcard at the closest encloser must be accounted for.
    let proof = nsec3_closest_encloser(nsec3s, qname, zone)?;
    if proof.opt_out {
        // RFC 5155 §6: unsigned delegations in an opt-out span have no NSEC3,
        // so this cannot tell "does not exist" from "exists, unsigned". Taking
        // it as proof would let the span's NSEC3 deny any unsigned zone under
        // it, such as every unsigned name in com.
        return Ok(None);
    }
    let wildcard = format!("*.{}", proof.encloser);
    match (&proof.wildcard, nxdomain) {
        (WildcardAt::Denied, true) => Ok(Some(format!(
            "NXDOMAIN proven: closest encloser {}, next-closer covered, wildcard covered",
            proof.encloser
        ))),
        (WildcardAt::Present(_), true) => {
            Err(format!("wildcard {} exists and would answer", wildcard))
        }
        (WildcardAt::Present(types), false) => {
            if types.contains(&qtype) || types.contains(&RecordType::CNAME) {
                Err(format!("wildcard {} would answer {}", wildcard, qtype))
            } else {
                Ok(Some(format!(
                    "NODATA proven: {} has no record of its own and wildcard {} lacks {}: closest encloser {}",
                    qname, wildcard, qtype, proof.encloser
                )))
            }
        }
        (WildcardAt::Denied, false) => Err(format!(
            "{} has no record of its own and there is no wildcard {}, which is NXDOMAIN, not this answer",
            qname, wildcard
        )),
        (WildcardAt::Unknown, _) => {
            *ask = Some(wildcard.clone());
            Err(format!("nothing shows whether wildcard {} exists", wildcard))
        }
    }
}

/// What the NSEC3 records say about the wildcard at the closest encloser.
enum WildcardAt {
    /// An NSEC3 covers its hash: there is none.
    Denied,
    /// An NSEC3 matches its hash: it exists, with these types.
    Present(Vec<RecordType>),
    /// Neither.
    Unknown,
}

struct ClosestEncloser {
    encloser: String,
    /// The NSEC3 covering the next-closer name has opt-out set (RFC 5155 §8.6).
    opt_out: bool,
    wildcard: WildcardAt,
}

/// RFC 5155 §8.3: find the closest encloser of `qname` and the NSEC3 that
/// covers its next-closer name. An error means `qname` is not shown to be
/// absent.
fn nsec3_closest_encloser(
    nsec3s: &[&ResourceRecord],
    qname: &str,
    zone: &str,
) -> Result<ClosestEncloser, String> {
    let (iterations, salt) = match &nsec3s[0].rdata {
        RData::NSEC3 {
            iterations, salt, ..
        } => (*iterations, salt.clone()),
        _ => return Err("not an NSEC3 record".to_string()),
    };
    let hash = |name: &str| nsec3_hash(name, iterations, &salt);

    // 1. Find the closest encloser: the longest ancestor of qname whose hash
    //    matches an NSEC3 owner exactly.
    let labels: Vec<&str> = qname.trim_end_matches('.').split('.').collect();
    let zone_labels = zone
        .trim_end_matches('.')
        .split('.')
        .filter(|s| !s.is_empty())
        .count();
    let mut closest_encloser: Option<String> = None;
    let mut next_closer: Option<String> = None;
    // Ancestors from the full name up to (and including) the zone apex.
    for start in 0..=labels.len().saturating_sub(zone_labels) {
        let candidate_labels = &labels[start..];
        if candidate_labels.is_empty() {
            break;
        }
        let candidate = format!("{}.", candidate_labels.join("."));
        if let Some(chash) = hash(&candidate) {
            if nsec3s.iter().any(|rr| nsec3_matches(rr, &chash)) {
                closest_encloser = Some(candidate);
                if start > 0 {
                    next_closer = Some(format!("{}.", labels[start - 1..].join(".")));
                }
                break;
            }
        }
    }

    let Some(ce) = closest_encloser else {
        return Err("no NSEC3 matches any closest encloser".to_string());
    };
    let Some(nc) = next_closer else {
        // qname itself matched an NSEC3 owner but had the type — handled above;
        // reaching here means the name provably exists, so NXDOMAIN is a lie.
        return Err("closest encloser equals the query name".to_string());
    };

    // 2. An NSEC3 must cover the next-closer name's hash.
    let nc_hash = hash(&nc).ok_or("cannot hash next-closer name")?;
    let nc_covered = nsec3s.iter().find(|rr| nsec3_covers(rr, &nc_hash));
    let Some(nc_rr) = nc_covered else {
        return Err("no NSEC3 covers the next-closer name".to_string());
    };

    // 3. What the records say about the wildcard *.<closest-encloser>, and
    //    whether the next-closer NSEC3 is opt-out (RFC 5155 §8.6).
    let opt_out = matches!(&nc_rr.rdata, RData::NSEC3 { flags, .. } if flags & 0x01 != 0);
    let wc_hash = hash(&format!("*.{}", ce)).ok_or("cannot hash wildcard")?;
    let present = nsec3s.iter().find_map(|rr| match &rr.rdata {
        RData::NSEC3 { type_bitmaps, .. } if nsec3_matches(rr, &wc_hash) => {
            Some(type_bitmaps.clone())
        }
        _ => None,
    });
    let wildcard = match present {
        Some(types) => WildcardAt::Present(types),
        None if nsec3s.iter().any(|rr| nsec3_covers(rr, &wc_hash)) => WildcardAt::Denied,
        None => WildcardAt::Unknown,
    };

    Ok(ClosestEncloser {
        encloser: ce,
        opt_out,
        wildcard,
    })
}

// === Wildcard expansion (RFC 4035 §5.3.4, RFC 5155 §8.8) ===

enum WildcardProof {
    /// The RRSIG label count matches the owner: nothing was synthesized.
    NotExpanded,
    /// Signed NSEC/NSEC3 records show the owner name does not exist, so the
    /// wildcard legitimately applied.
    Proven(String),
    /// The NSEC3 covering the next-closer name has opt-out set. An unsigned
    /// delegation could sit in that span, so the answer is not provably the
    /// wildcard's — and not provably forged either.
    OptOut(String),
    /// Synthesized from a wildcard, with no valid proof that it should be.
    Unproven(String),
}

/// What an RRSIG's Labels field holds for `name` (RFC 4034 §3.1.3): the root
/// and a leading "*" label are not counted.
fn rrsig_label_count(name: &str) -> usize {
    let labels: Vec<&str> = name
        .trim_end_matches('.')
        .split('.')
        .filter(|l| !l.is_empty())
        .collect();
    labels.len() - usize::from(labels.first() == Some(&"*"))
}

/// How many trailing labels two names share.
fn common_suffix_labels(a: &str, b: &str) -> usize {
    let labels = |n: &'_ str| -> Vec<String> {
        n.trim_end_matches('.')
            .rsplit('.')
            .filter(|l| !l.is_empty())
            .map(|l| l.to_ascii_lowercase())
            .collect()
    };
    labels(a)
        .iter()
        .zip(labels(b).iter())
        .take_while(|(x, y)| x == y)
        .count()
}

/// The `rtype` (NSEC or NSEC3) records in `authority` whose RRset carries a
/// valid RRSIG from `zone`. Anything else is dropped rather than trusted,
/// because anyone on the path can add an unsigned record to a response.
///
/// A denial record whose own RRSIG is wildcard-expanded is dropped as well.
/// Otherwise the NSEC at "*.zone" could be replayed under any owner name in
/// the zone, and so made to cover whatever range a forger needs.
fn verified_denial_records<'a>(
    authority: &'a [ResourceRecord],
    rtype: RecordType,
    zone: &str,
    dnskeys: &[&ResourceRecord],
    now: u32,
) -> Vec<&'a ResourceRecord> {
    let mut verified = Vec::new();
    for sig in rrsigs_covering(authority, rtype) {
        let RData::RRSIG { signer, labels, .. } = &sig.rdata else {
            continue;
        };
        if !names_equal(signer, zone) || rrsig_label_count(&sig.name) != *labels as usize {
            continue;
        }
        let rrset: Vec<&ResourceRecord> = authority
            .iter()
            .filter(|rr| rr.rtype == rtype && names_equal(&rr.name, &sig.name))
            .collect();
        if !rrset.is_empty() && verify_rrsig(&rrset, sig, dnskeys, now).is_ok() {
            verified.extend(rrset);
        }
    }
    verified
}

/// If the RRset at `owner` was synthesized from a wildcard, check the proof
/// in `authority` that `owner` itself does not exist.
fn prove_wildcard_expansion(
    authority: &[ResourceRecord],
    owner: &str,
    labels: u8,
    zone: &str,
    dnskeys: &[&ResourceRecord],
    now: u32,
) -> WildcardProof {
    if rrsig_label_count(owner) <= labels as usize {
        return WildcardProof::NotExpanded;
    }
    let nsecs = verified_denial_records(authority, RecordType::NSEC, zone, dnskeys, now);
    let nsec3s = verified_denial_records(authority, RecordType::NSEC3, zone, dnskeys, now);
    wildcard_proof(&nsecs, &nsec3s, owner, labels as usize)
}

/// The proof itself, over denial records already known to be validly signed.
/// `labels` is the RRSIG label count, which is smaller than `owner`'s.
fn wildcard_proof(
    nsecs: &[&ResourceRecord],
    nsec3s: &[&ResourceRecord],
    owner: &str,
    labels: usize,
) -> WildcardProof {
    // The wildcard's parent is the closest encloser of the owner; the name one
    // label longer is the next-closer name, which must not exist.
    let parts: Vec<&str> = owner.trim_end_matches('.').split('.').collect();
    let encloser = format!("{}.", parts[parts.len() - labels..].join("."));
    let next_closer = format!("{}.", parts[parts.len() - labels - 1..].join("."));
    let wildcard = format!("*.{}", encloser.trim_start_matches('.'));

    if !nsec3s.is_empty() {
        // RFC 5155 §8.8: an NSEC3 must cover the next-closer name.
        let covering = nsec3s.iter().find(|rr| {
            let RData::NSEC3 {
                iterations, salt, ..
            } = &rr.rdata
            else {
                return false;
            };
            nsec3_hash(&next_closer, *iterations, salt).is_some_and(|h| nsec3_covers(rr, &h))
        });
        return match covering {
            Some(rr) if matches!(&rr.rdata, RData::NSEC3 { flags, .. } if flags & 0x01 != 0) => {
                WildcardProof::OptOut(format!(
                    "wildcard {} expansion: NSEC3 covering next-closer {} is opt-out",
                    wildcard, next_closer
                ))
            }
            Some(_) => WildcardProof::Proven(format!(
                "wildcard {} expansion proven: NSEC3 covers next-closer {}",
                wildcard, next_closer
            )),
            None => WildcardProof::Unproven(format!(
                "wildcard {} answer, but no NSEC3 covers the next-closer name {}",
                wildcard, next_closer
            )),
        };
    }

    // RFC 4035 §5.3.4: an NSEC must cover the owner name.
    let Some(rr) = nsecs.iter().find(|rr| nsec_covers(rr, owner)) else {
        return WildcardProof::Unproven(format!(
            "wildcard {} answer, but no signed NSEC proves {} does not exist",
            wildcard, owner
        ));
    };
    let RData::NSEC { next_domain, .. } = &rr.rdata else {
        unreachable!("nsec_covers matched an NSEC");
    };
    // The NSEC's two ends are names that do exist. If either shares more
    // labels with the owner than the wildcard's parent does, something closer
    // than the wildcard exists and this wildcard could not have applied.
    let nearest =
        common_suffix_labels(owner, &rr.name).max(common_suffix_labels(owner, next_domain));
    if nearest != labels {
        return WildcardProof::Unproven(format!(
            "wildcard {} answer, but NSEC {} \u{2192} {} puts the closest encloser elsewhere",
            wildcard, rr.name, next_domain
        ));
    }
    WildcardProof::Proven(format!(
        "wildcard {} expansion proven: NSEC {} < {} < {}",
        wildcard, rr.name, owner, next_domain
    ))
}

