    fn full_message(wire: &[u8]) -> DnsMessage {
        DnsMessage::parse(wire).expect("fixture parses")
    }

    fn denial_fetch(
        dnskey_zone: &'static str,
        dnskey_wire: &'static [u8],
    ) -> impl Fn(&str, RecordType) -> Result<DnsMessage, DnsError> {
        move |name: &str, rtype: RecordType| {
            if rtype == RecordType::DNSKEY && name == dnskey_zone {
                DnsMessage::parse(dnskey_wire)
            } else {
                // Chain-to-root beyond the signing zone is not exercised here;
                // return an empty message so the chain walk degrades to a
                // clear error rather than touching the network.
                DnsMessage::parse(&[0u8; 12])
            }
        }
    }

    #[test]
    fn nsec_nodata_denial_is_proven() {
        let answer = full_message(NSEC_NODATA);
        let fetch = denial_fetch("nlnetlabs.nl.", NSEC_NODATA_DNSKEY);
        // HINFO (type 13) NODATA on nlnetlabs.nl.
        let outcome = validate_denial(
            &answer,
            "nlnetlabs.nl",
            RecordType::Unknown(13),
            FIXED_DENIAL_NOW,
            &fetch,
        )
        .unwrap();
        match outcome {
            DenialOutcome::Proven { denial_links, .. } => {
                assert!(denial_links.iter().all(|l| l.ok));
                assert!(denial_links
                    .iter()
                    .any(|l| l.detail.contains("NODATA proven")));
            }
            DenialOutcome::Bogus { reason, .. } => panic!("expected proven, got bogus: {}", reason),
            DenialOutcome::Unsigned => panic!("expected proven, got unsigned"),
            DenialOutcome::Unverifiable(zone) => {
                panic!("expected proven, got unverifiable: {}", zone)
            }
        }
    }

    #[test]
    fn nsec3_nodata_denial_is_proven() {
        let answer = full_message(NSEC3_NODATA);
        let fetch = denial_fetch("iana.org.", NSEC3_NODATA_DNSKEY);
        let outcome = validate_denial(
            &answer,
            "iana.org",
            RecordType::Unknown(13),
            FIXED_DENIAL_NOW,
            &fetch,
        )
        .unwrap();
        assert!(
            matches!(outcome, DenialOutcome::Proven { .. }),
            "iana.org HINFO NODATA should be proven via NSEC3"
        );
    }

    #[test]
    fn nsec3_nxdomain_closest_encloser_is_proven() {
        let answer = full_message(NSEC3_NXDOMAIN);
        let fetch = denial_fetch("verisign.com.", NSEC3_NXDOMAIN_DNSKEY);
        let outcome = validate_denial(
            &answer,
            "nope12345xyz.verisign.com",
            RecordType::A,
            FIXED_DENIAL_NOW,
            &fetch,
        )
        .unwrap();
        match outcome {
            DenialOutcome::Proven { denial_links, .. } => {
                assert!(denial_links
                    .iter()
                    .any(|l| l.detail.contains("NXDOMAIN proven")));
            }
            DenialOutcome::Bogus { reason, .. } => panic!("expected proven, got bogus: {}", reason),
            DenialOutcome::Unsigned => panic!("expected proven, got unsigned"),
            DenialOutcome::Unverifiable(zone) => {
                panic!("expected proven, got unverifiable: {}", zone)
            }
        }
    }

    #[test]
    fn tampered_nsec3_hash_is_not_proven() {
        // Flip a bit in the answer's authority NSEC3 next_hashed via raw
        // mutation: corrupt the wire then re-parse. A broken signature must
        // yield Bogus, never Proven.
        let mut wire = NSEC3_NXDOMAIN.to_vec();
        // Corrupt a byte well inside the authority section (past the header
        // and question) — lands in an NSEC3/RRSIG rdata region.
        let i = wire.len() - 40;
        wire[i] ^= 0xFF;
        let answer = match DnsMessage::parse(&wire) {
            Ok(m) => m,
            Err(_) => return, // corruption broke parsing entirely: also fine
        };
        let fetch = denial_fetch("verisign.com.", NSEC3_NXDOMAIN_DNSKEY);
        let outcome = validate_denial(
            &answer,
            "nope12345xyz.verisign.com",
            RecordType::A,
            FIXED_DENIAL_NOW,
            &fetch,
        )
        .unwrap();
        assert!(
            !matches!(outcome, DenialOutcome::Proven { .. }),
            "a tampered denial must not be proven SECURE"
        );
    }

    #[test]
    fn unsigned_negative_answer_is_insecure_not_bogus() {
        // A NODATA-shaped message with an empty authority section.
        let mut msg = full_message(NSEC_NODATA);
        msg.authority.clear();
        let fetch = denial_fetch("nlnetlabs.nl.", NSEC_NODATA_DNSKEY);
        let outcome = validate_denial(
            &msg,
            "nlnetlabs.nl",
            RecordType::Unknown(13),
            FIXED_DENIAL_NOW,
            &fetch,
        )
        .unwrap();
        assert!(matches!(outcome, DenialOutcome::Unsigned));
    }

    #[test]
    fn nsec3_hash_matches_rfc5155_shape() {
        // The hash is 20 bytes (SHA-1) regardless of iterations.
        let h = nsec3_hash("example.com.", 5, &[0xAA, 0xBB]).unwrap();
        assert_eq!(h.len(), 20);
        // Deterministic: same inputs, same output.
        assert_eq!(h, nsec3_hash("example.com.", 5, &[0xAA, 0xBB]).unwrap());
        // Iterations matter.
        assert_ne!(h, nsec3_hash("example.com.", 6, &[0xAA, 0xBB]).unwrap());
    }

    #[test]
    fn base32hex_decode_roundtrips_encode() {
        use crate::protocol::record::base32_encode_hex;
        let data = vec![0xDE, 0xAD, 0xBE, 0xEF, 0x01, 0x23, 0x45];
        let encoded = base32_encode_hex(&data);
        assert_eq!(base32hex_decode(&encoded).unwrap(), data);
    }

    #[test]
    fn canonical_name_ordering_follows_rfc4034() {
        use std::cmp::Ordering;
        assert_eq!(
            canonical_name_cmp("example.com", "example.com"),
            Ordering::Equal
        );
        // Shorter name (parent) sorts before its child.
        assert_eq!(
            canonical_name_cmp("example.com", "a.example.com"),
            Ordering::Less
        );
        // Rightmost label dominates.
        assert_eq!(
            canonical_name_cmp("z.example.com", "a.example.org"),
            Ordering::Less
        );
        // Case-insensitive.
        assert_eq!(
            canonical_name_cmp("EXAMPLE.com", "example.com"),
            Ordering::Equal
        );
    }

