    fn answers(wire: &[u8]) -> Vec<ResourceRecord> {
        DnsMessage::parse(wire).expect("fixture parses").answers
    }

    fn keys(records: &[ResourceRecord]) -> Vec<&ResourceRecord> {
        records
            .iter()
            .filter(|rr| rr.rtype == RecordType::DNSKEY)
            .collect()
    }

    #[test]
    fn root_ksk_matches_builtin_trust_anchor() {
        let root = answers(ROOT_DNSKEY);
        let matched = keys(&root).iter().any(|key| {
            ROOT_ANCHORS.iter().any(|anchor| {
                key_tag(&key.raw_rdata) == anchor.key_tag
                    && ds_digest(".", key, 2).as_deref() == Some(anchor.digest)
            })
        });
        assert!(matched, "live root DNSKEY should match an IANA anchor");
    }

    #[test]
    fn real_ecdsa_rrsig_verifies_over_answer_rrset() {
        let recs = answers(CF_A);
        let rrset: Vec<&ResourceRecord> =
            recs.iter().filter(|r| r.rtype == RecordType::A).collect();
        let rrsig = recs
            .iter()
            .find(|r| matches!(&r.rdata, RData::RRSIG { type_covered, .. } if *type_covered == RecordType::A))
            .expect("fixture has RRSIG");
        let key_recs = answers(CF_DNSKEY);
        let dnskeys = keys(&key_recs);
        let tag = verify_rrsig(&rrset, rrsig, &dnskeys, FIXED_NOW).expect("signature verifies");
        assert!(tag > 0);
    }

    #[test]
    fn tampered_rdata_fails_verification() {
        let mut recs = answers(CF_A);
        // Flip one bit in an A record's rdata.
        if let Some(rr) = recs.iter_mut().find(|r| r.rtype == RecordType::A) {
            rr.raw_rdata[0] ^= 1;
        }
        let rrset: Vec<&ResourceRecord> =
            recs.iter().filter(|r| r.rtype == RecordType::A).collect();
        let rrsig = recs
            .iter()
            .find(|r| matches!(&r.rdata, RData::RRSIG { type_covered, .. } if *type_covered == RecordType::A))
            .unwrap();
        let key_recs = answers(CF_DNSKEY);
        assert!(verify_rrsig(&rrset, rrsig, &keys(&key_recs), FIXED_NOW).is_err());
    }

    #[test]
    fn signature_time_window_is_enforced() {
        let recs = answers(CF_A);
        let rrset: Vec<&ResourceRecord> =
            recs.iter().filter(|r| r.rtype == RecordType::A).collect();
        let rrsig = recs
            .iter()
            .find(|r| matches!(&r.rdata, RData::RRSIG { type_covered, .. } if *type_covered == RecordType::A))
            .unwrap();
        let key_recs = answers(CF_DNSKEY);
        let dnskeys = keys(&key_recs);
        let expired = verify_rrsig(&rrset, rrsig, &dnskeys, u32::MAX).unwrap_err();
        assert!(expired.contains("expired"), "{}", expired);
        let early = verify_rrsig(&rrset, rrsig, &dnskeys, 0).unwrap_err();
        assert!(early.contains("not yet valid"), "{}", early);
    }

    #[test]
    fn ds_digest_links_child_ksk_to_parent() {
        let ds_recs = answers(COM_DS);
        let key_recs = answers(CF_DNSKEY);
        let matched = ds_recs
            .iter()
            .filter_map(|rr| match &rr.rdata {
                RData::DS {
                    key_tag: tag,
                    digest_type,
                    digest,
                    ..
                } => Some((tag, digest_type, digest)),
                _ => None,
            })
            .any(|(tag, dt, digest)| {
                keys(&key_recs).iter().any(|key| {
                    key_tag(&key.raw_rdata) == *tag
                        && ds_digest("cloudflare.com.", key, *dt).as_deref()
                            == Some(digest.as_slice())
                })
            });
        assert!(matched, "cloudflare.com DS should match its KSK");
    }

    /// The chain walk asks for a zone's DNSKEY from several places, so it used
    /// to issue eight queries for five distinct records - three of them
    /// immediate repeats. Each duplicate is a network round trip, and +validate
    /// is round-trip bound, so this pins that they stay gone.
    #[test]
    fn validation_never_fetches_the_same_record_twice() {
        use std::sync::Mutex;
        let log: Mutex<Vec<(String, RecordType)>> = Mutex::new(Vec::new());
        let fetch = |name: &str, rtype: RecordType| -> Result<DnsMessage, DnsError> {
            log.lock().unwrap().push((name.to_string(), rtype));
            let wire = match (name, rtype) {
                ("cloudflare.com.", RecordType::DNSKEY) => CF_DNSKEY,
                ("cloudflare.com.", RecordType::DS) => COM_DS,
                ("com.", RecordType::DNSKEY) => COM_DNSKEY,
                ("com.", RecordType::DS) => COM_DS_AT_ROOT,
                (".", RecordType::DNSKEY) => ROOT_DNSKEY,
                other => panic!("unexpected fetch: {:?}", other),
            };
            DnsMessage::parse(wire)
        };
        let answer = DnsMessage::parse(CF_A).unwrap();
        let report =
            validate_with(&answer, "cloudflare.com", RecordType::A, FIXED_NOW, &fetch).unwrap();
        assert_eq!(
            report.status,
            ChainStatus::Secure,
            "chain must still verify"
        );

        let fetches = log.lock().unwrap().clone();
        let mut unique = fetches.clone();
        unique.sort_by(|a, b| (a.0.as_str(), a.1.to_u16()).cmp(&(b.0.as_str(), b.1.to_u16())));
        unique.dedup();
        assert_eq!(
            fetches.len(),
            unique.len(),
            "duplicate fetches crept back in: {:?}",
            fetches
        );
        // cloudflare.com DNSKEY + DS, com DNSKEY + DS, root DNSKEY.
        assert_eq!(fetches.len(), 5, "unexpected fetch set: {:?}", fetches);
    }

    #[test]
    fn full_chain_validates_secure_from_fixtures() {
        let fetch = |name: &str, rtype: RecordType| -> Result<DnsMessage, DnsError> {
            let wire = match (name, rtype) {
                ("cloudflare.com.", RecordType::DNSKEY) => CF_DNSKEY,
                ("cloudflare.com.", RecordType::DS) => COM_DS,
                ("com.", RecordType::DNSKEY) => COM_DNSKEY,
                ("com.", RecordType::DS) => COM_DS_AT_ROOT,
                (".", RecordType::DNSKEY) => ROOT_DNSKEY,
                other => panic!("unexpected fetch: {:?}", other),
            };
            DnsMessage::parse(wire)
        };
        let answer = DnsMessage::parse(CF_A).unwrap();
        let report =
            validate_with(&answer, "cloudflare.com", RecordType::A, FIXED_NOW, &fetch).unwrap();
        for link in &report.links {
            assert!(link.ok, "link failed: {} {}", link.zone, link.detail);
        }
        assert_eq!(report.status, ChainStatus::Secure);
        // Chain touches all three zones.
        let zones: Vec<&str> = report.links.iter().map(|l| l.zone.as_str()).collect();
        assert!(zones.contains(&"cloudflare.com."));
        assert!(zones.contains(&"com."));
        assert!(zones.contains(&"."));
    }

    #[test]
    fn key_tag_matches_rrsig_reference() {
        // The fixture RRSIG names the key that signed it; our computed tag
        // over that DNSKEY's RDATA must agree.
        let recs = answers(CF_A);
        let sig_tag = recs
            .iter()
            .find_map(|r| match &r.rdata {
                RData::RRSIG {
                    key_tag,
                    type_covered,
                    ..
                } if *type_covered == RecordType::A => Some(*key_tag),
                _ => None,
            })
            .unwrap();
        let key_recs = answers(CF_DNSKEY);
        assert!(
            keys(&key_recs)
                .iter()
                .any(|k| key_tag(&k.raw_rdata) == sig_tag),
            "no DNSKEY matches RRSIG key tag {}",
            sig_tag
        );
    }

    #[test]
    fn wildcard_owner_reduces_to_rrsig_label_count() {
        assert_eq!(wildcard_owner("a.b.example.com.", 2), "*.example.com.");
        assert_eq!(wildcard_owner("example.com.", 2), "example.com.");
        assert_eq!(wildcard_owner("www.example.com.", 3), "www.example.com.");
        // Root has zero labels and must never be wildcard-adjusted.
        assert_eq!(wildcard_owner(".", 0), ".");
    }

    #[test]
    fn rsa_dnskey_der_encoding_is_wellformed() {
        // explen=1, exponent 65537 (0x010001), tiny "modulus".
        let key = [3u8, 0x01, 0x00, 0x01, 0xC9, 0x00, 0x01];
        let der = rsa_dnskey_to_der(&key).unwrap();
        assert_eq!(der[0], 0x30); // SEQUENCE
                                  // modulus INTEGER gets a leading zero (0xC9 high bit set)
        assert_eq!(&der[2..4], &[0x02, 0x04]);
        assert_eq!(&der[4..8], &[0x00, 0xC9, 0x00, 0x01]);
    }

    #[test]
    fn parent_zone_walks_toward_root() {
        assert_eq!(parent_zone("cloudflare.com."), "com.");
        assert_eq!(parent_zone("com."), ".");
    }

    /// The same replay against a negative answer: www.internet.nl exists, and
    /// the renamed wildcard NSEC used to "prove" that it does not.
    #[test]
    fn replayed_wildcard_nsec_cannot_prove_nxdomain() {
        let mut answer = full_message(WILDCARD_OWNER_NSEC);
        for rr in &mut answer.authority {
            if rr.name == "*.internet.nl." {
                rr.name = "a.internet.nl.".to_string();
            }
        }
        let fetch = denial_fetch("internet.nl.", WILDCARD_NSEC_DNSKEY);
        let outcome = validate_denial(
            &answer,
            "www.internet.nl",
            RecordType::A,
            FIXED_WILDCARD_NOW,
            &fetch,
        )
        .unwrap();
        assert!(
            matches!(&outcome, DenialOutcome::Bogus { reason, .. } if reason.contains("no validly signed NSEC")),
            "a replayed wildcard NSEC must not prove NXDOMAIN"
        );

        // Left alone, the same message is a valid NODATA proof for the name
        // it was actually issued for.
        let genuine = full_message(WILDCARD_OWNER_NSEC);
        let outcome = validate_denial(
            &genuine,
            "*.internet.nl",
            RecordType::Unknown(13),
            FIXED_WILDCARD_NOW,
            &fetch,
        )
        .unwrap();
        assert!(matches!(outcome, DenialOutcome::Proven { .. }));
    }

