    /// Serve the DNSKEY set of the listed zones and nothing else. Tests pair
    /// it with validate_pinned, which takes those zones as verified.
    fn zone_keys(
        zones: &'static [(&'static str, &'static [u8])],
    ) -> impl Fn(&str, RecordType) -> Result<DnsMessage, DnsError> {
        move |name: &str, rtype: RecordType| match zones.iter().find(|(zone, _)| *zone == name) {
            Some((_, wire)) if rtype == RecordType::DNSKEY => DnsMessage::parse(wire),
            _ => DnsMessage::parse(&[0u8; 12]),
        }
    }

    fn has_link(report: &ValidationReport, text: &str) -> bool {
        report.links.iter().any(|l| l.ok && l.detail.contains(text))
    }

    #[test]
    fn cname_chain_validates_every_step() {
        let answer = full_message(CNAME_CHAIN);
        let fetch = zone_keys(&[("sidn.nl.", SIDN_DNSKEY)]);
        let report = validate_pinned(&answer, "www.sidn.nl", RecordType::A, &fetch, &["sidn.nl."]);
        assert!(
            has_link(
                &report,
                "CNAME www.sidn.nl. \u{2192} sidn.nl. RRSIG verified"
            ),
            "CNAME step missing"
        );
        assert!(has_link(&report, "A RRSIG verified"), "A step missing");
        assert!(report.links.iter().all(|l| l.ok));
        assert_eq!(report.status, ChainStatus::Secure);
    }

    /// The CNAME is what ties the signed A record to the name that was asked
    /// for. Unsigned, it could have been written by anyone, so validation must
    /// stop there rather than vouch for wherever it points.
    #[test]
    fn unsigned_cname_does_not_lend_the_targets_signature() {
        let mut answer = full_message(CNAME_CHAIN);
        answer.answers.retain(|rr| {
            !matches!(&rr.rdata, RData::RRSIG { type_covered, .. } if *type_covered == RecordType::CNAME)
        });
        let fetch = served(
            &[("sidn.nl.", RecordType::DNSKEY, SIDN_DNSKEY)],
            &["nl.", "sidn.nl."],
        );
        let report = validate_pinned(&answer, "www.sidn.nl", RecordType::A, &fetch, &["sidn.nl."]);
        // sidn.nl is signed all the way down, so a CNAME without a signature
        // is not an unsigned zone's CNAME; it is a stripped one.
        assert!(
            matches!(&report.status, ChainStatus::Bogus(why) if why.contains("www.sidn.nl.")),
            "{:?}",
            report.status
        );
        assert!(!has_link(&report, "A RRSIG verified"));
    }

    #[test]
    fn cname_into_an_unsigned_zone_is_insecure() {
        let answer = full_message(CNAME_TO_UNSIGNED);
        let fetch = served(
            &[
                ("state.gov.", RecordType::DNSKEY, STATE_GOV_DNSKEY),
                ("net.", RecordType::DNSKEY, NET_DNSKEY),
                ("cloudfront.net.", RecordType::DS, DS_CLOUDFRONT_NET),
            ],
            &["net."],
        );
        let report = validate_pinned(
            &answer,
            "www.state.gov",
            RecordType::A,
            &fetch,
            &["state.gov.", "net."],
        );
        assert!(has_link(&report, "CNAME www.state.gov. \u{2192}"));
        // The target's A records carry no RRSIG, and net's opt-out NSEC3 shows
        // that cloudfront.net may be an unsigned delegation.
        assert!(!has_link(&report, "A RRSIG verified"));
        assert!(has_link(&report, "opt-out NSEC3 by net. covers it"));
        assert!(
            matches!(&report.status, ChainStatus::Insecure(why) if why.contains("cloudfront.net. has no DS and sits in an opt-out span")),
            "{:?}",
            report.status
        );
    }

    #[test]
    fn negative_answer_at_the_end_of_a_cname_chain_is_proven() {
        let answer = full_message(CNAME_NODATA);
        let fetch = zone_keys(&[("sidn.nl.", SIDN_DNSKEY)]);
        let report = validate_pinned(
            &answer,
            "www.sidn.nl",
            RecordType::Unknown(29),
            &fetch,
            &["sidn.nl."],
        );
        assert!(has_link(&report, "CNAME www.sidn.nl. \u{2192} sidn.nl."));
        // The denial is for the CNAME's target, not for the name queried.
        assert!(
            has_link(&report, "NODATA proven: NSEC at sidn.nl."),
            "{:?}",
            report.links.iter().map(|l| &l.detail).collect::<Vec<_>>()
        );
        assert_eq!(report.status, ChainStatus::Secure);
    }

    fn cloudflare_chain(name: &str, rtype: RecordType) -> Result<DnsMessage, DnsError> {
        let wire: &[u8] = match (name, rtype) {
            ("cloudflare.com.", RecordType::DNSKEY) => CF_DNSKEY,
            ("cloudflare.com.", RecordType::DS) => COM_DS,
            ("com.", RecordType::DNSKEY) => COM_DNSKEY,
            ("com.", RecordType::DS) => COM_DS_AT_ROOT,
            (".", RecordType::DNSKEY) => ROOT_DNSKEY,
            _ => &[0u8; 12],
        };
        DnsMessage::parse(wire)
    }

    /// A genuine, correctly signed RRset for cloudflare.com says nothing about
    /// any other name, however it is presented.
    #[test]
    fn signed_answer_for_another_name_is_not_secure() {
        let answer = DnsMessage::parse(CF_A).unwrap();
        // Control: for its own name the fixture is Secure.
        let own = validate_with(
            &answer,
            "cloudflare.com",
            RecordType::A,
            FIXED_NOW,
            &cloudflare_chain,
        )
        .unwrap();
        assert_eq!(own.status, ChainStatus::Secure);

        let other = validate_with(
            &answer,
            "www.cloudflare.com",
            RecordType::A,
            FIXED_NOW,
            &cloudflare_chain,
        )
        .unwrap();
        assert!(
            matches!(other.status, ChainStatus::Bogus(_)),
            "{:?}",
            other.status
        );
        assert!(!has_link(&other, "A RRSIG verified"));
    }

    #[test]
    fn rrsig_from_a_zone_that_does_not_contain_the_name_is_bogus() {
        // cloudflare.com's records and signature, presented as victim.org's.
        // The signer is refused before any key is fetched.
        let mut answer = DnsMessage::parse(CF_A).unwrap();
        for rr in &mut answer.answers {
            rr.name = "victim.org.".to_string();
        }
        let no_fetch = |name: &str, rtype: RecordType| -> Result<DnsMessage, DnsError> {
            panic!("unexpected fetch: {} {}", name, rtype)
        };
        let report =
            validate_with(&answer, "victim.org", RecordType::A, FIXED_NOW, &no_fetch).unwrap();
        assert!(
            matches!(&report.status, ChainStatus::Bogus(why) if why.contains("cannot sign")),
            "{:?}",
            report.status
        );
    }

    #[test]
    fn rrsig_label_count_above_the_owners_is_bogus() {
        let mut answer = DnsMessage::parse(CF_A).unwrap();
        for rr in &mut answer.answers {
            if let RData::RRSIG { labels, .. } = &mut rr.rdata {
                *labels = 5;
            }
        }
        let report = validate_with(
            &answer,
            "cloudflare.com",
            RecordType::A,
            FIXED_NOW,
            &cloudflare_chain,
        )
        .unwrap();
        assert!(
            matches!(&report.status, ChainStatus::Bogus(why) if why.contains("label count")),
            "{:?}",
            report.status
        );
    }

    #[test]
    fn chain_walk_stops_at_a_zone_already_verified() {
        let mut trusted = vec!["com.".to_string()];
        let report = chain_to_root(
            "cloudflare.com.".to_string(),
            FIXED_NOW,
            &cloudflare_chain,
            Vec::new(),
            &mut trusted,
        )
        .unwrap();
        assert_eq!(report.status, ChainStatus::Secure);
        // cloudflare.com is verified against com's DS; com and the root are not
        // walked again.
        assert!(report.links.iter().all(|l| l.zone == "cloudflare.com."));
        assert!(trusted.iter().any(|z| z == "cloudflare.com."));
    }

    #[test]
    fn denial_signed_by_a_zone_outside_the_name_is_not_a_proof() {
        // nlnetlabs.nl's genuine NODATA proof cannot deny a name in example.org.
        let answer = full_message(NSEC_NODATA);
        let fetch = denial_fetch("nlnetlabs.nl.", NSEC_NODATA_DNSKEY);
        let outcome = validate_denial(
            &answer,
            "example.org",
            RecordType::Unknown(13),
            FIXED_DENIAL_NOW,
            &fetch,
        )
        .unwrap();
        assert!(matches!(outcome, DenialOutcome::Unsigned));
    }

    #[test]
    fn in_zone_compares_whole_labels() {
        assert!(in_zone("www.example.com.", "example.com."));
        assert!(in_zone("example.com", "example.com."));
        assert!(in_zone("EXAMPLE.com.", "example.COM."));
        assert!(in_zone("example.com.", "."));
        assert!(!in_zone("example.com.", "www.example.com."));
        assert!(!in_zone("badexample.com.", "example.com."));
    }

