    const DNAME_ZONES: &[(&str, &[u8])] = &[
        ("sidnlabs.nl.", WILDCARD_NSEC3_DNSKEY),
        ("example.nl.", EXAMPLE_NL_DNSKEY),
    ];

    fn validate_dname(answer: &DnsMessage, qname: &str) -> ValidationReport {
        let fetch = zone_keys(DNAME_ZONES);
        validate_pinned(
            answer,
            qname,
            RecordType::A,
            &fetch,
            &["sidnlabs.nl.", "example.nl."],
        )
    }

    #[test]
    fn dname_redirection_validates_as_a_unit() {
        let report = validate_dname(&full_message(DNAME_CHAIN), "www.dname.sidnlabs.nl");
        assert!(has_link(
            &report,
            "DNAME dname.sidnlabs.nl. \u{2192} example.nl. RRSIG verified"
        ));
        assert!(has_link(
            &report,
            "CNAME www.dname.sidnlabs.nl. \u{2192} www.example.nl. synthesized from DNAME"
        ));
        assert!(has_link(&report, "A RRSIG verified"));
        assert!(report.links.iter().all(|l| l.ok));
        assert_eq!(report.status, ChainStatus::Secure);
    }

    #[test]
    fn negative_answer_behind_a_dname_is_proven() {
        let report = validate_dname(
            &full_message(DNAME_NXDOMAIN),
            "nope12345xyz.dname.sidnlabs.nl",
        );
        assert!(has_link(&report, "synthesized from DNAME"));
        // The name that does not exist is the one in the DNAME's target zone.
        assert!(
            has_link(&report, "NXDOMAIN proven")
                && report
                    .links
                    .iter()
                    .any(|l| l.zone == "example.nl."
                        && l.detail.contains("nope12345xyz.example.nl.")),
            "{:?}",
            report.links.iter().map(|l| &l.detail).collect::<Vec<_>>()
        );
        assert_eq!(report.status, ChainStatus::Secure);
    }

    /// The synthesized CNAME is unsigned, so the only thing that makes it
    /// trustworthy is that it is exactly what the signed DNAME produces.
    #[test]
    fn cname_that_the_dname_does_not_produce_is_bogus() {
        let mut answer = full_message(DNAME_CHAIN);
        for rr in &mut answer.answers {
            if let RData::CNAME(target) = &mut rr.rdata {
                *target = "www.sidn.nl.".to_string();
            }
        }
        let report = validate_dname(&answer, "www.dname.sidnlabs.nl");
        assert!(
            matches!(&report.status, ChainStatus::Bogus(why) if why.contains("does not match its DNAME")),
            "{:?}",
            report.status
        );
        assert!(report
            .links
            .iter()
            .any(|l| !l.ok && l.detail.contains("www.example.nl.")));
    }

    #[test]
    fn unsigned_dname_does_not_vouch_for_its_cname() {
        let mut answer = full_message(DNAME_CHAIN);
        answer.answers.retain(|rr| {
            !matches!(&rr.rdata, RData::RRSIG { type_covered, .. } if *type_covered == RecordType::DNAME)
        });
        let report = validate_dname(&answer, "www.dname.sidnlabs.nl");
        assert!(matches!(report.status, ChainStatus::Bogus(_)));
        assert!(!has_link(&report, "synthesized from DNAME"));
        assert!(!has_link(&report, "A RRSIG verified"));
    }

    #[test]
    fn dname_only_redirects_names_below_its_owner() {
        // The same signed DNAME, asked to explain a CNAME at a name it does
        // not sit above, and at its own owner name.
        let fetch = zone_keys(DNAME_ZONES);
        for owner in ["www.other.sidnlabs.nl.", "dname.sidnlabs.nl."] {
            let mut answer = full_message(DNAME_CHAIN);
            for rr in &mut answer.answers {
                if rr.rtype == RecordType::CNAME {
                    rr.name = owner.to_string();
                }
            }
            let mut links = Vec::new();
            let step =
                verify_dname_synthesis(&answer, owner, FIXED_WILDCARD_NOW, &fetch, &mut links)
                    .unwrap();
            assert!(step.is_none(), "{} is not below the DNAME", owner);
            assert!(links.is_empty());
        }
    }

    #[test]
    fn dname_rdata_is_lowercased_in_canonical_form() {
        // RFC 4034 §6.2 lists DNAME among the types whose RDATA names are
        // lowercased before signing.
        let rr = ResourceRecord {
            name: "dname.example.com.".to_string(),
            rtype: RecordType::DNAME,
            rclass: RecordClass::IN,
            ttl: 300,
            rdata: RData::DNAME("Target.EXAMPLE.net.".to_string()),
            raw_rdata: encode_name("Target.EXAMPLE.net.").unwrap(),
        };
        assert_eq!(
            canonical_rdata(&rr).unwrap(),
            encode_name("target.example.net.").unwrap()
        );
    }

    // === Unsigned delegations (captured live from 1.1.1.1 on 2026-10-12,
    // inside the FIXED_WILDCARD_NOW signature window). ===
    // DS_TEST_DNSSEC_TOOLS is the DS query for test.dnssec-tools.org: NODATA,
    // with dnssec-tools.org's NSEC showing NS and no DS at that name.
    // DS_CLOUDFRONT_NET is the DS query for cloudfront.net: net's opt-out
    // NSEC3 covers the name.
