    const ALG5_ZONE: &[(&str, RecordType, &[u8])] = &[
        ("d2a5n1.rootcanary.net.", RecordType::DS, ALG5_DS),
        ("rootcanary.net.", RecordType::DNSKEY, ROOTCANARY_DNSKEY),
    ];

    /// RFC 4035 §5.2: a zone whose DS names only algorithms the validator
    /// lacks is unsigned to that validator, not broken.
    #[test]
    fn zone_signed_only_with_an_unsupported_algorithm_is_insecure() {
        let fetch = served(ALG5_ZONE, &[]);
        for (wire, qname, qtype) in [
            (ALG5_SOA, "d2a5n1.rootcanary.net", RecordType::SOA),
            (
                ALG5_NXDOMAIN,
                "nope12345xyz.d2a5n1.rootcanary.net",
                RecordType::A,
            ),
        ] {
            let report = validate_pinned(
                &full_message(wire),
                qname,
                qtype,
                &fetch,
                &["rootcanary.net."],
            );
            assert!(
                matches!(&report.status, ChainStatus::Insecure(why) if why.contains("algorithm 5")),
                "{}: {:?}",
                qname,
                report.status
            );
            // The parent's signature on the DS is what makes that believable.
            assert!(has_link(&report, "DS RRSIG verified by rootcanary.net."));
            assert!(report.links.iter().all(|l| l.ok));
        }
    }

    /// The same answer, where the zone's chain verifies with an algorithm
    /// that is implemented. Then signatures that could have been checked
    /// exist, and an answer carrying only the others has had them removed.
    #[test]
    fn unsupported_signatures_alone_are_bogus_in_a_zone_that_has_others() {
        let fetch = served(ALG5_ZONE, &[]);
        let report = validate_pinned(
            &full_message(ALG5_SOA),
            "d2a5n1.rootcanary.net",
            RecordType::SOA,
            &fetch,
            &["d2a5n1.rootcanary.net."],
        );
        assert!(
            matches!(&report.status, ChainStatus::Bogus(why) if why.contains("could verify are missing")),
            "{:?}",
            report.status
        );
    }

    #[test]
    fn unsupported_algorithm_claim_needs_the_parents_signature() {
        // Strip the RRSIG from the DS: now "algorithm 5 only" is just a claim.
        let stripped = |name: &str, rtype: RecordType| -> Result<DnsMessage, DnsError> {
            let mut msg = served(ALG5_ZONE, &[])(name, rtype)?;
            if rtype == RecordType::DS {
                msg.answers.retain(|rr| rr.rtype != RecordType::RRSIG);
            }
            Ok(msg)
        };
        let report = validate_pinned(
            &full_message(ALG5_SOA),
            "d2a5n1.rootcanary.net",
            RecordType::SOA,
            &stripped,
            &["rootcanary.net."],
        );
        assert!(
            matches!(report.status, ChainStatus::Bogus(_)),
            "{:?}",
            report.status
        );
    }

    #[test]
    fn unsupported_only_needs_every_ds_to_be_unusable() {
        let ds = |algorithm: u8, digest_type: u8| {
            let mut msg = ds_present("example.com.");
            if let RData::DS {
                algorithm: a,
                digest_type: d,
                ..
            } = &mut msg.answers[0].rdata
            {
                *a = algorithm;
                *d = digest_type;
            }
            msg.answers.remove(0)
        };
        let check = |set: &[ResourceRecord]| {
            let refs: Vec<&ResourceRecord> = set.iter().collect();
            unsupported_only(&refs)
        };
        assert_eq!(check(&[]), None);
        assert_eq!(check(&[ds(13, 2)]), None);
        assert_eq!(check(&[ds(5, 2)]), Some("5".to_string()));
        assert_eq!(check(&[ds(5, 2), ds(16, 2)]), Some("5/16".to_string()));
        // One usable DS is enough to expect verifiable signatures.
        assert_eq!(check(&[ds(5, 2), ds(13, 2)]), None);
        // A known algorithm behind a digest type that is not implemented.
        assert_eq!(check(&[ds(13, 3)]), Some("13".to_string()));
    }

    /// A covering NSEC shows the name has no record of its own. Whether that
    /// is NXDOMAIN, NODATA or a lie depends on the wildcard that could have
    /// answered instead.
    #[test]
    fn nsec_cover_proof_accounts_for_the_wildcard() {
        let gap = nsec("a.example.com.", "t.example.com.");
        // example.com < *.example.com < a.example.com: no wildcard.
        let no_wildcard = nsec("example.com.", "a.example.com.");
        let prove = |nsecs: &[&ResourceRecord], nxdomain: bool| {
            prove_nsec(
                nsecs,
                "sub.example.com.",
                RecordType::A,
                nxdomain,
                &mut None,
            )
        };

        let proven = prove(&[&gap, &no_wildcard], true).unwrap();
        assert!(
            proven.starts_with("NXDOMAIN proven: NSEC a.example.com. < sub.example.com. <"),
            "{}",
            proven
        );
        // The cover alone: nothing says a wildcard would not have answered.
        let alone = prove(&[&gap], true).unwrap_err();
        assert!(
            alone.contains("wildcard *.example.com. is not denied"),
            "{}",
            alone
        );
        // A wildcard that exists makes NXDOMAIN false.
        let with_txt = nsec_with("*.example.com.", "a.example.com.", &[RecordType::TXT]);
        let exists = prove(&[&gap, &with_txt], true).unwrap_err();
        assert!(exists.contains("exists and would answer"), "{}", exists);

        // NOERROR with the same cover is NODATA, if the wildcard lacks the type.
        let nodata = prove(&[&gap, &with_txt], false).unwrap();
        assert!(
            nodata.starts_with(
                "NODATA proven: sub.example.com. has no record of its own and wildcard *.example.com. lacks A"
            ),
            "{}",
            nodata
        );
        for types in [&[RecordType::A][..], &[RecordType::CNAME][..]] {
            let answers = nsec_with("*.example.com.", "a.example.com.", types);
            let err = prove(&[&gap, &answers], false).unwrap_err();
            assert!(err.contains("would answer A"), "{}", err);
        }
        let unknown = prove(&[&gap], false).unwrap_err();
        assert!(
            unknown.contains("no NSEC shows what wildcard"),
            "{}",
            unknown
        );
    }

    #[test]
    fn nsec_cover_with_names_below_is_an_empty_non_terminal() {
        let ent = nsec("a.example.com.", "x.sub.example.com.");
        let nodata =
            prove_nsec(&[&ent], "sub.example.com.", RecordType::A, false, &mut None).unwrap();
        assert!(nodata.contains("is an empty non-terminal"), "{}", nodata);
        // It exists, so NXDOMAIN for it is false.
        assert!(prove_nsec(&[&ent], "sub.example.com.", RecordType::A, true, &mut None).is_err());
    }

    /// The forgery the wildcard check stops, with real records: take a genuine
    /// wildcard answer, drop the answer, keep its proof, and call it NXDOMAIN.
    #[test]
    fn wildcard_answers_proof_cannot_be_replayed_as_nxdomain() {
        for (wire, qname, zone, dnskey) in [
            (
                WILDCARD_NSEC,
                "nope12345xyz.internet.nl",
                "internet.nl.",
                WILDCARD_NSEC_DNSKEY,
            ),
            (
                WILDCARD_NSEC3,
                "nope12345xyz.sidnlabs.nl",
                "sidnlabs.nl.",
                WILDCARD_NSEC3_DNSKEY,
            ),
        ] {
            let mut answer = full_message(wire);
            answer.answers.clear();
            answer.header.rcode = Rcode::NxDomain;
            let fetch = denial_fetch(zone, dnskey);
            let outcome =
                validate_denial(&answer, qname, RecordType::TXT, FIXED_WILDCARD_NOW, &fetch)
                    .unwrap();
            assert!(
                matches!(outcome, DenialOutcome::Bogus { .. }),
                "{}: a name the wildcard answers must not be deniable",
                zone
            );
        }
    }

    /// net's NSEC3 covering cloudfront.net is opt-out. It is genuine and it
    /// proves nothing about whether cloudfront.net exists.
    #[test]
    fn opt_out_span_is_not_a_denial() {
        let mut answer = full_message(DS_CLOUDFRONT_NET);
        answer.header.rcode = Rcode::NxDomain;
        // Keep the NSEC3 records and their signatures. The fixture's SOA was
        // re-signed minutes before capture, after FIXED_WILDCARD_NOW.
        answer.authority.retain(|rr| {
            rr.rtype == RecordType::NSEC3
                || matches!(&rr.rdata, RData::RRSIG { type_covered, .. } if *type_covered == RecordType::NSEC3)
        });
        let fetch = denial_fetch("net.", NET_DNSKEY);
        let outcome = validate_denial(
            &answer,
            "cloudfront.net",
            RecordType::A,
            FIXED_WILDCARD_NOW,
            &fetch,
        )
        .unwrap();
        assert!(
            matches!(outcome, DenialOutcome::Unsigned),
            "an opt-out span must not prove NXDOMAIN for an unsigned zone"
        );
    }

    fn truncated() -> DnsMessage {
        // QR, TC and RD set, no records, and an OPT record so that only the TC
        // bit is wrong with it.
        DnsMessage::parse(&[
            0x12, 0x34, 0x83, 0x80, 0, 0, 0, 0, 0, 0, 0, 1, // header, ARCOUNT 1
            0, 0, 41, 0x04, 0xD0, 0, 0, 0x80, 0, 0, 0, // OPT, DO set
        ])
        .unwrap()
    }

    /// SERVFAIL with an OPT record, as a validating resolver sends it.
    fn servfail() -> DnsMessage {
        DnsMessage::parse(&[
            0x12, 0x34, 0x81, 0x82, 0, 0, 0, 0, 0, 0, 0, 1, // header, RCODE 2
            0, 0, 41, 0x04, 0xD0, 0, 0, 0x80, 0, 0, 0, // OPT, DO set
        ])
        .unwrap()
    }

    /// NOERROR with an OPT record and no answer.
    fn empty_answer() -> DnsMessage {
        DnsMessage::parse(&[
            0x12, 0x34, 0x81, 0x80, 0, 0, 0, 0, 0, 0, 0, 1, // header
            0, 0, 41, 0x04, 0xD0, 0, 0, 0x80, 0, 0, 0, // OPT, DO set
        ])
        .unwrap()
    }

    /// Header only: NOERROR, nothing in it, and no OPT record.
    fn without_edns() -> DnsMessage {
        DnsMessage::parse(&[0x12, 0x34, 0x81, 0x80, 0, 0, 0, 0, 0, 0, 0, 0]).unwrap()
    }

    #[test]
    fn unusable_response_is_asked_for_again() {
        use std::cell::Cell;
        assert!(truncated().header.tc && truncated().edns.is_some());
        assert!(without_edns().edns.is_none());

        // Truncated, then without EDNS, then whole: the third is the one used.
        let calls = Cell::new(0);
        let message = complete_response("org.", RecordType::DNSKEY, Duration::ZERO, || {
            calls.set(calls.get() + 1);
            match calls.get() {
                1 => Ok(truncated()),
                2 => Ok(without_edns()),
                _ => DnsMessage::parse(CF_DNSKEY),
            }
        })
        .unwrap();
        assert_eq!(calls.get(), 3);
        assert!(!message.answers.is_empty());

        // An empty answer is a real answer for any type but DNSKEY.
        let calls = Cell::new(0);
        complete_response("example.org.", RecordType::DS, Duration::ZERO, || {
            calls.set(calls.get() + 1);
            Ok(empty_answer())
        })
        .unwrap();
        assert_eq!(calls.get(), 1);
    }

    #[test]
    fn response_that_stays_unusable_is_an_error_not_a_verdict() {
        use std::cell::Cell;
        for (bad, text) in [
            (
                truncated as fn() -> DnsMessage,
                "a truncated response for org. DNSKEY",
            ),
            (without_edns, "a response without EDNS for org. DNSKEY"),
            (servfail, "a failure response for org. DNSKEY"),
            (empty_answer, "an empty answer for org. DNSKEY"),
        ] {
            let calls = Cell::new(0);
            let err = complete_response("org.", RecordType::DNSKEY, Duration::ZERO, || {
                calls.set(calls.get() + 1);
                Ok(bad())
            })
            .expect_err("an unusable response must not be returned as data");
            assert_eq!(calls.get(), INCOMPLETE_RETRIES + 1);
            assert!(err.to_string().contains(text), "{}", err);
        }
    }

    #[test]
    fn answer_without_edns_is_not_judged() {
        let no_fetch = |name: &str, rtype: RecordType| -> Result<DnsMessage, DnsError> {
            panic!("unexpected fetch: {} {}", name, rtype)
        };
        let report = validate_with(
            &without_edns(),
            "example.com",
            RecordType::A,
            FIXED_NOW,
            &no_fetch,
        )
        .unwrap();
        assert!(
            matches!(&report.status, ChainStatus::Insecure(why) if why.contains("no EDNS")),
            "{:?}",
            report.status
        );
    }

